        i ??= d!;
    }
    void M(string? s, string s2, dynamic d)
    {
        s! ??= s2; // 3
        s ??= s2!;
        s! ??= d; // 4
        s ??= d!;
    }
}", options: WithNullableEnable());
            comp.VerifyDiagnostics(
                // (6,9): error CS8598: The suppression operator is not allowed in this context
                //         i! ??= i2; // 1
