                // [My(new (string, string bob)[] { }, new object[] { }, new dynamic[] { })]
                Diagnostic(ErrorCode.ERR_BadAttributeParamType, "My").WithArguments("y", "dynamic[]").WithLocation(7, 2)
                );
        }

