                //       c.ToString(); // 2 (not tracked through assignment)
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "c").WithLocation(22, 7)
                );

            VerifyAnnotationsAndMetadata(c, "C.op_Implicit", NotNullWhenTrue);
        }

