{
    void Test(object o, object o2) => throw null!;

    void M(object? o, object o2)
    {
        switch (o, o2)
        {
            case (not null, null):
                Test(o, o2); // 1
                break;
            case (not null, not null): // 2
                Test(o, o2);
                break;
            default:
                Test(o, o2); // 3
                break;
        }
    }

    void M2(object? o, object o2)
    {
        switch (true, (o, o2))
        {
            case (true, (not null, null)):
                Test(o, o2); // 4
                break;
            case (_, (not null, not null)):
                Test(o, o2); // 5
                break;
            default:
                Test(o, o2); // 6
                break;
        };
    }
}
