            // Arguably we could just see through to the constant value and know it's non-null,
            // but it feels like the user should just fix the type of their 'const' in this scenario.
            var comp = CreateNullableCompilation(new[] { source });
            comp.VerifyDiagnostics(
                // (8,17): warning CS8602: Dereference of a possibly null reference.
                //         var x = s1.ToString();
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "s1").WithLocation(8, 17));
        }

