            var source =
@"using System.Diagnostics.CodeAnalysis;
class Program
{
    static bool F1<T>(T t, [MaybeNullWhen(true)]out T t2) => throw null!;
    static bool F2<T>(T t, [MaybeNullWhen(true)]out T t2) where T : class => throw null!;
    static bool F3<T>(T t, [MaybeNullWhen(true)]out T? t2) where T : class => throw null!;
    static bool F4<T>(T t, [MaybeNullWhen(true)]out T t2) where T : struct => throw null!;
    static bool F5<T>(T? t, [MaybeNullWhen(true)]out T? t2) where T : struct => throw null!;
    static void M1<T>(T t1)
    {
        _ = F1(t1, out var s2) // 0
            ? s2.ToString() // 1
            : s2.ToString(); // 2
    }
    static void M2<T>(T t2) where T : class
    {
        _ = F1(t2, out var s3)
            ? s3.ToString() // 3
            : s3.ToString();

        _ = F2(t2, out var s4)
            ? s4.ToString() // 4
            : s4.ToString();

        _ = F3(t2, out var s5)
            ? s5.ToString() // 5
            : s5.ToString(); // 6

        t2 = null; // 7
        _ = F1(t2, out var s6)
            ? s6.ToString() // 8
            : s6.ToString(); // 9

        _ = F2(t2, out var s7) // 10
            ? s7.ToString() // 11
            : s7.ToString(); // 12

        _ = F3(t2, out var s8) // 13
            ? s8.ToString() // 14
            : s8.ToString(); // 15
    }
    static void M3<T>(T? t3) where T : class
    {
        _ = F1(t3, out var s9)
            ? s9.ToString() // 16
            : s9.ToString(); // 17

        _ = F2(t3, out var s10) // 18
            ? s10.ToString() // 19
            : s10.ToString(); // 20

        _ = F3(t3, out var s11) // 21
            ? s11.ToString() // 22
            : s11.ToString(); // 23

        if (t3 == null) return;
        _ = F1(t3, out var s12)
            ? s12.ToString() // 24
            : s12.ToString();

        _ = F2(t3, out var s13)
            ? s13.ToString() // 25
            : s13.ToString();

        _ = F3(t3, out var s14)
            ? s14.ToString() // 26
            : s14.ToString(); // 27
    }
    static void M4<T>(T t4) where T : struct
    {
        _ = F1(t4, out var s15)
            ? s15.ToString()
            : s15.ToString();

        _ = F4(t4, out var s16)
            ? s16.ToString()
            : s16.ToString();
    }
    static void M5<T>(T? t5) where T : struct
    {
        _ = F1(t5, out var s17)
            ? s17.Value // 28
            : s17.Value; // 29

        _ = F5(t5, out var s18)
            ? s18.Value // 30
            : s18.Value; // 31

        if (t5 == null) return;
        _ = F1(t5, out var s19)
            ? s19.Value // 32
            : s19.Value; // 33

        _ = F5(t5, out var s20)
            ? s20.Value // 34
            : s20.Value; // 35
    }
}";
