    public static explicit operator C(A a) => throw null!;
}
public class C
{
    public void Main()
    {
        A a = new A();
        _ = IsNull((C)a)
            ? a.ToString() // 1
            : a.ToString();
    }
    public static bool IsNull([MaybeNullWhen(true)] C c) => throw null!;
}
", MaybeNullWhenAttributeDefinition }, options: WithNullableEnable());

            c.VerifyDiagnostics(
                // (13,15): warning CS8602: Dereference of a possibly null reference.
                //             ? a.ToString() // 1
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "a").WithLocation(13, 15)
                );
        }

        [Fact]
        public void MaybeNull_OnExplicitConversion()
        {
            var c = CreateCompilation(new[] { @"
using System.Diagnostics.CodeAnalysis;
public class A
{
    public static explicit operator C(A? a) => throw null!;
}
public class C
{
    public void Main()
    {
        A a = new A();
        _ = IsNull((C)a)
            ? a.ToString()
            : a.ToString();
    }
    public static bool IsNull([MaybeNull] C c) => throw null!;
}
", MaybeNullAttributeDefinition }, options: WithNullableEnable());

            // Both diagnostics are unexpected
            // We should not blindly strip conversions when learning that a value is null.
            // In this case, we shouldn't infer that `a` may be null from the fact that `(C)a` may be null.
            // Tracked by https://github.com/dotnet/roslyn/issues/36164
            c.VerifyDiagnostics(
                // (13,15): warning CS8602: Dereference of a possibly null reference.
                //             ? a.ToString()
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "a").WithLocation(13, 15),
                // (14,15): warning CS8602: Dereference of a possibly null reference.
                //             : a.ToString();
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "a").WithLocation(14, 15)
                );
        }

        [Fact]
        public void MaybeNull_Property()
        {
            // Warn on redundant nullability attributes (P3, P5)? https://github.com/dotnet/roslyn/issues/36073
            var lib_cs =
@"using System.Diagnostics.CodeAnalysis;
public class COpen<TOpen>
{
    [MaybeNull]public TOpen P1 { get; set; } = default!;
}
public class CClass<TClass> where TClass : class
{
    [MaybeNull]public TClass P2 { get; set; } = null!;
    [MaybeNull]public TClass? P3 { get; set; } = null;
}
public class CStruct<TStruct> where TStruct : struct
{
    [MaybeNull]public TStruct P4 { get; set; }
    [MaybeNull]public TStruct? P5 { get; set; }
}";
            var lib = CreateNullableCompilation(new[] { MaybeNullAttributeDefinition, lib_cs });
            lib.VerifyDiagnostics();

            var source = @"
class C
{
    static void M1<T>(T t1)
    {
        new COpen<T>().P1 = t1;
        new COpen<T>().P1.ToString(); // 0, 1

        var xOpen = new COpen<T>();
        xOpen.P1 = t1;
        xOpen.P1.ToString(); // 2, 3

        var xOpen2 = new COpen<T>();
        if (xOpen2.P1 is object) // 4
        {
            xOpen2.P1.ToString();
        }
    }
    static void M2<T>(T t2) where T : class
    {
        new COpen<T>().P1.ToString(); // 5
        new CClass<T>().P2.ToString(); // 6
        new CClass<T>().P3.ToString(); // 7
    }
    static void M4<T>(T t4) where T : struct
    {
        new COpen<T>().P1.ToString();
        new CStruct<T>().P4.ToString();
        new COpen<T?>().P1.Value.ToString(); // 8
        new CStruct<T>().P5.Value.ToString(); // 9
    }
}";
            var expected = new[]
            {
                // (7,9): warning CS8602: Dereference of a possibly null reference.
                //         new COpen<T>().P1.ToString(); // 0, 1
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "new COpen<T>().P1").WithLocation(7, 9),
                // (11,9): warning CS8602: Dereference of a possibly null reference.
                //         xOpen.P1.ToString(); // 2, 3
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "xOpen.P1").WithLocation(11, 9),
                // (21,9): warning CS8602: Dereference of a possibly null reference.
                //         new COpen<T>().P1.ToString(); // 5
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "new COpen<T>().P1").WithLocation(21, 9),
                // (22,9): warning CS8602: Dereference of a possibly null reference.
                //         new CClass<T>().P2.ToString(); // 6
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "new CClass<T>().P2").WithLocation(22, 9),
                // (23,9): warning CS8602: Dereference of a possibly null reference.
                //         new CClass<T>().P3.ToString(); // 7
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "new CClass<T>().P3").WithLocation(23, 9),
                // (29,9): warning CS8629: Nullable value type may be null.
                //         new COpen<T?>().P1.Value.ToString(); // 8
                Diagnostic(ErrorCode.WRN_NullableValueTypeMayBeNull, "new COpen<T?>().P1").WithLocation(29, 9),
                // (30,9): warning CS8629: Nullable value type may be null.
                //         new CStruct<T>().P5.Value.ToString(); // 9
                Diagnostic(ErrorCode.WRN_NullableValueTypeMayBeNull, "new CStruct<T>().P5").WithLocation(30, 9)
            };

            var comp = CreateNullableCompilation(source, references: new[] { lib.EmitToImageReference() });
            comp.VerifyDiagnostics(expected);

            var comp2 = CreateNullableCompilation(new[] { source, lib_cs, MaybeNullAttributeDefinition });
            comp2.VerifyDiagnostics(expected);

            CompileAndVerify(comp2, sourceSymbolValidator: symbolValidator, symbolValidator: symbolValidator);

            void symbolValidator(ModuleSymbol m)
            {
                bool isSource = !(m is PEModuleSymbol);
                var copen = (NamedTypeSymbol)m.GlobalNamespace.GetMember("COpen");
                var copenAttributes = copen.GetAttributes().Select(a => a.ToString());
                if (isSource)
                {
                    AssertEx.Empty(copenAttributes);
                }
                else
                {
                    AssertEx.Equal(new[] { "System.Runtime.CompilerServices.NullableContextAttribute(1)", "System.Runtime.CompilerServices.NullableAttribute(0)" }, copenAttributes);
                }

                var property = copen.GetMembers().OfType<PropertySymbol>().Single();
                var propertyAttributes = property.GetAttributes().Select(a => a.ToString());
                if (isSource)
                {
                    AssertEx.Equal(new[] { "System.Diagnostics.CodeAnalysis.MaybeNullAttribute" }, propertyAttributes);
                }
                else
                {
                    AssertEx.Empty(propertyAttributes);
                }

                var getter = property.GetMethod;
                var getterAttributes = getter.GetAttributes().Select(a => a.ToString());
                if (isSource)
                {
                    AssertEx.Empty(getterAttributes);
                }
                else
                {
                    AssertEx.Equal(new[] { "System.Runtime.CompilerServices.CompilerGeneratedAttribute" }, getterAttributes);
                }

                var getterReturnAttributes = getter.GetReturnTypeAttributes().Select(a => a.ToString());
                Assert.Equal(FlowAnalysisAnnotations.MaybeNull, getter.ReturnTypeFlowAnalysisAnnotations);
                if (isSource)
                {
                    AssertEx.Empty(getterReturnAttributes);
                }
                else
                {
                    AssertEx.Equal(new[] { "System.Diagnostics.CodeAnalysis.MaybeNullAttribute" }, getterReturnAttributes);
                }

                var setter = property.SetMethod;
                var setterAttributes = setter.GetAttributes();
                if (isSource)
                {
                    AssertEx.Empty(setterAttributes);
                }
                else
                {
                    AssertEx.Equal(new[] { "System.Runtime.CompilerServices.CompilerGeneratedAttribute" }, setterAttributes.Select(a => a.ToString()));
                }

                Assert.Equal(FlowAnalysisAnnotations.None, setter.ReturnTypeFlowAnalysisAnnotations);
                var setterReturnAttributes = setter.GetReturnTypeAttributes();
                AssertEx.Empty(setterReturnAttributes);
            }
        }

        [Fact]
        public void MaybeNull_Property_InCompoundAssignment()
        {
            var source = @"
using System.Diagnostics.CodeAnalysis;
class C
{
    [MaybeNull] C Property { get; set; } = null!;
    public static C operator+(C one, C other) => throw null!;

    void M(C c)
    {
        Property += c; // 1
    }
}";

            var comp = CreateNullableCompilation(new[] { source, MaybeNullAttributeDefinition });
            comp.VerifyDiagnostics(
                // (10,9): warning CS8604: Possible null reference argument for parameter 'one' in 'C C.operator +(C one, C other)'.
