        [Fact]
        public void MaybeNull_Property_OnVirtualProperty()
        {
            var source = @"
using System.Diagnostics.CodeAnalysis;
public class Base
{
    [MaybeNull] public virtual string P => throw null!;
    public virtual string P2 => throw null!;
}
public class C : Base
{
    public override string P => throw null!;
    [MaybeNull] public override string P2 => throw null!; // 0

    static void M(C c, Base b)
    {
        b.P.ToString(); // 1
        c.P.ToString();

        b.P2.ToString();
        c.P2.ToString(); // 2
    }
}";
            var comp = CreateNullableCompilation(new[] { source, MaybeNullAttributeDefinition });
            comp.VerifyDiagnostics(
                // (11,46): warning CS8764: Return type doesn't match overridden member because of nullability attributes.
                //     [MaybeNull] public override string P2 => throw null!; // 0
                Diagnostic(ErrorCode.WRN_TopLevelNullabilityMismatchInReturnTypeOnOverride, "throw null!").WithLocation(11, 46),
                // (15,9): warning CS8602: Dereference of a possibly null reference.
                //         b.P.ToString(); // 1
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "b.P").WithLocation(15, 9),
                // (19,9): warning CS8602: Dereference of a possibly null reference.
                //         c.P2.ToString(); // 2
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "c.P2").WithLocation(19, 9)
                );
        }

