            var source =
@"using System.Diagnostics.CodeAnalysis;
class Program
{
    static bool F1<T>(T t, [NotNullWhen(false)]out T t2) => throw null!;
    static bool F2<T>(T t, [NotNullWhen(false)]out T t2) where T : class => throw null!;
    static bool F3<T>(T t, [NotNullWhen(false)]out T? t2) where T : class => throw null!;
    static bool F4<T>(T t, [NotNullWhen(false)]out T t2) where T : struct => throw null!;
    static bool F5<T>(T? t, [NotNullWhen(false)]out T? t2) where T : struct => throw null!;
    static void M1<T>(T t1)
    {
        _ = F1(t1, out var s2)
            ? s2.ToString() // 1
            : s2.ToString();
    }
    static void M2<T>(T t2) where T : class
    {
        _ = F1(t2, out var s3)
            ? s3.ToString()
            : s3.ToString();

        _ = F2(t2, out var s4)
            ? s4.ToString()
            : s4.ToString();

        _ = F3(t2, out var s5)
            ? s5.ToString() // 2
            : s5.ToString();

        t2 = null; // 3
        _ = F1(t2, out var s6)
            ? s6.ToString() // 4
            : s6.ToString();

        _ = F2(t2, out var s7) // 5
            ? s7.ToString() // 6
            : s7.ToString();

        _ = F3(t2, out var s8) // 7
            ? s8.ToString() // 8
            : s8.ToString();
    }
    static void M3<T>(T? t3) where T : class
    {
        _ = F1(t3, out var s9)
            ? s9.ToString() // 9
            : s9.ToString();

        _ = F2(t3, out var s10) // 10
            ? s10.ToString() // 11
            : s10.ToString();

        _ = F3(t3, out var s11) // 12
            ? s11.ToString() // 13
            : s11.ToString();

        if (t3 == null) return;
        _ = F1(t3, out var s12)
            ? s12.ToString()
            : s12.ToString();

        _ = F2(t3, out var s13)
            ? s13.ToString()
            : s13.ToString();

        _ = F3(t3, out var s14)
            ? s14.ToString() // 14
            : s14.ToString();
    }
    static void M4<T>(T t4) where T : struct
    {
        _ = F1(t4, out var s15)
            ? s15.ToString()
            : s15.ToString();

        _ = F4(t4, out var s16)
            ? s16.ToString()
            : s16.ToString();
    }
    static void M5<T>(T? t5) where T : struct
    {
        _ = F1(t5, out var s17)
            ? s17.Value // 15
            : s17.Value;

        _ = F5(t5, out var s18)
            ? s18.Value // 16
            : s18.Value;

        if (t5 == null) return;
        _ = F1(t5, out var s19)
            ? s19.Value // 17
            : s19.Value;

        _ = F5(t5, out var s20)
            ? s20.Value // 18
            : s20.Value;
    }
}";
