        [Fact]
        public void NotNullIfNotNull_Return()
        {
            // NotNullIfNotNull isn't enforced in scenarios like the following
            var lib_cs =
@"using System.Diagnostics.CodeAnalysis;
public class C
{
    [return: NotNullIfNotNull(""p"")] public string? M(string? p) => null;
}";
            var source = @"
class D
{
    static void M(C c, string? p1, string? p2)
    {
        _ = p1 ?? throw null!;
        c.M(p1).ToString();
        c.M(p2).ToString(); // 1
    }
}";
            var expected = new[]
            {
                // (8,9): warning CS8602: Dereference of a possibly null reference.
                //         c.M(p2).ToString(); // 1
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "c.M(p2)").WithLocation(8, 9)
            };

            var lib = CreateNullableCompilation(new[] { NotNullIfNotNullAttributeDefinition, lib_cs });
            var comp = CreateNullableCompilation(source, references: new[] { lib.EmitToImageReference() });
            comp.VerifyDiagnostics(expected);

            var comp2 = CreateNullableCompilation(new[] { source, lib_cs, NotNullIfNotNullAttributeDefinition });
            comp2.VerifyDiagnostics(expected);
            CompileAndVerify(comp2);
        }

