        [Fact, WorkItem(49964, "https://github.com/dotnet/roslyn/issues/49964")]
        public void AdjustPropertyState_MaybeDefaultInput_MaybeNullOutput()
        {
            var source = @"
using System.Diagnostics.CodeAnalysis;

public class C<T> {
    [AllowNull]
    T Prop { get; set; }

    public C() { }

    public C(int unused)
    {
        M1(Prop); // 1
    }

    public void M()
    {
        Prop = default;
        M1(Prop); // 2
        Prop.ToString();
    }

    public void M1(T t) { }
}
";
            var comp = CreateNullableCompilation(new[] { source, AllowNullAttributeDefinition });
            // It's not clear whether diagnostic 1 and 2 are appropriate.
            // Going by the principle of "if you put a good value in, you will get a good value out",
            // it seems like property state should be MaybeNull after assigning a MaybeDefault to the property.
            // https://github.com/dotnet/roslyn/issues/49964

            // Note that the lack of constructor exit warning in 'C()' is expected due to presence of 'AllowNull' on the property declaration.
            comp.VerifyDiagnostics(
                // (12,12): warning CS8604: Possible null reference argument for parameter 't' in 'void C<T>.M1(T t)'.
                //         M1(Prop); // 1
                Diagnostic(ErrorCode.WRN_NullReferenceArgument, "Prop").WithArguments("t", "void C<T>.M1(T t)").WithLocation(12, 12),
                // (18,12): warning CS8604: Possible null reference argument for parameter 't' in 'void C<T>.M1(T t)'.
                //         M1(Prop); // 2
                Diagnostic(ErrorCode.WRN_NullReferenceArgument, "Prop").WithArguments("t", "void C<T>.M1(T t)").WithLocation(18, 12));
        }

