            var source1 = @"
using System.Diagnostics.CodeAnalysis;

public static class C1
{
    [return: NotNullIfNotNull(""s"")]
    public static string? M1(string? s = null!) => s;
}
";
            var source2 = @"
class C2
{
    static void M2()
    {
        _ = C1.M1().ToString();
        _ = C1.M1(null).ToString();
        _ = C1.M1(""hello"").ToString();
    }
}
";
            var comp1 = CreateNullableCompilation(new[] { source1, source2, NotNullIfNotNullAttributeDefinition });
            // technically since the argument has not-null state, the return value should have not-null state here,
            // but it is such a corner case that it is unlikely to be of interest to modify the current behavior
            comp1.VerifyDiagnostics(
                // (6,13): warning CS8602: Dereference of a possibly null reference.
                //         _ = C1.M1().ToString();
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "C1.M1()").WithLocation(6, 13),
                // (7,13): warning CS8602: Dereference of a possibly null reference.
                //         _ = C1.M1(null).ToString();
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "C1.M1(null)").WithLocation(7, 13));

            var reference = CreateNullableCompilation(new[] { source1, NotNullIfNotNullAttributeDefinition }).EmitToImageReference();
            var comp2 = CreateNullableCompilation(source2, references: new[] { reference });
            comp2.VerifyDiagnostics(
                // (6,13): warning CS8602: Dereference of a possibly null reference.
                //         _ = C1.M1().ToString();
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "C1.M1()").WithLocation(6, 13),
                // (7,13): warning CS8602: Dereference of a possibly null reference.
                //         _ = C1.M1(null).ToString();
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "C1.M1(null)").WithLocation(7, 13));
        }

