                // (18,16): warning CS8601: Possible null reference assignment.
                //         X2(ref f2, bar); // 1, warn on outbound assignment
                Diagnostic(ErrorCode.WRN_NullReferenceAssignment, "f2", isSuppressed: false).WithLocation(18, 16)
                );
