                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "s").WithLocation(13, 9),
                // (14,9): warning CS8602: Dereference of a possibly null reference.
                //         v2.ToString(); // 3
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "v2").WithLocation(14, 9),
