        [Fact, WorkItem(37081, "https://github.com/dotnet/roslyn/issues/37081")]
        public void DoesNotReturn_Simple()
        {
            string lib_cs = @"
using System.Diagnostics.CodeAnalysis;
public class C
{
    [DoesNotReturn] public static void Throw() => throw null!;
}
";
            string source = @"
class D
{
    void Main(object? o)
    {
        string unassigned;
        C.Throw();
        o.ToString(); // unreachable for purpose of nullability analysis so no warning
        unassigned.ToString(); // 1, reachable for purpose of definite assignment
    }
}
";
            // Should [DoesNotReturn] affect all flow analyses? https://github.com/dotnet/roslyn/issues/37081
            var expected = new[]
            {
                // (9,9): error CS0165: Use of unassigned local variable 'unassigned'
                //         unassigned.ToString(); // 1, reachable for purpose of definite assignment
                Diagnostic(ErrorCode.ERR_UseDefViolation, "unassigned").WithArguments("unassigned").WithLocation(9, 9)
            };

            var lib = CreateNullableCompilation(new[] { lib_cs, DoesNotReturnAttributeDefinition });
            var comp = CreateNullableCompilation(source, references: new[] { lib.EmitToImageReference() });
            comp.VerifyDiagnostics(expected);

            var comp2 = CreateNullableCompilation(new[] { source, lib_cs, DoesNotReturnAttributeDefinition });
            comp2.VerifyDiagnostics(expected);
        }

