    {
        x.ToString();
        x = null;
    }

    void M3([MaybeNull]out string x)
    {
        x = null;
        (x, _) = (null, 1);
    }

    void M4([NotNull]out string? x)
    {
        x = null;
        (x, _) = (null, 1);
    } // 2

    [return: MaybeNull] string M5()
    {
        return null;
    }

    [return: NotNull] string? M6()
    {
        return null; // 3
    }

    void M7([NotNull]string x)
