        [Fact]
        public void AllowNull_Field()
        {
            // Warn on misused nullability attributes (f3, f4, f5)? https://github.com/dotnet/roslyn/issues/36073
            var lib_cs =
@"using System.Diagnostics.CodeAnalysis;
public class COpen<TOpen>
{
    [AllowNull]public TOpen f1 = default!;
}
public class CClass<TClass> where TClass : class
{
    [AllowNull]public TClass f2 = null;
    [AllowNull]public TClass? f3 = null;
}
public class CStruct<TStruct> where TStruct : struct
{
    [AllowNull]public TStruct f4;
    [AllowNull]public TStruct? f5;
}
";

            var lib = CreateNullableCompilation(new[] { AllowNullAttributeDefinition, lib_cs });

            var source = @"
using System.Diagnostics.CodeAnalysis;
class C
{
    static void M1<T>([MaybeNull] T t1)
    {
        new COpen<T>().f1 = t1;
    }
    static void M2<T>(T t2) where T : class
    {
        new COpen<T>().f1 = t2;
        new CClass<T>().f2 = t2;
        new CClass<T>().f3 = t2;
        t2 = null; // 1
        new COpen<T>().f1 = t2;
        new CClass<T>().f2 = t2;
        new CClass<T>().f3 = t2;

        var xOpen = new COpen<T>();
        xOpen.f1 = null;
        xOpen.f1.ToString(); // 2

        var xClass = new CClass<T>();
        xClass.f2 = null;
        xClass.f2.ToString(); // 3
        xClass.f3 = null;
        xClass.f3.ToString(); // 4
    }
    static void M3<T>(T? t3) where T : class
    {
        new COpen<T>().f1 = t3;
        new CClass<T>().f2 = t3;
        new CClass<T>().f3 = t3;
        if (t3 == null) return;
        new COpen<T>().f1 = t3;
        new CClass<T>().f2 = t3;
        new CClass<T>().f3 = t3;
    }
    static void M4<T>(T t4) where T : struct
    {
        new COpen<T>().f1 = t4;
        new CStruct<T>().f4 = t4;
    }
    static void M5<T>(T? t5) where T : struct
    {
        new COpen<T?>().f1 = t5;
        new CStruct<T>().f5 = t5;
        if (t5 == null) return;
        new COpen<T?>().f1 = t5;
        new CStruct<T>().f5 = t5;
    }
}";
            var expected = new[]
            {
                // (14,14): warning CS8600: Converting null literal or possible null value to non-nullable type.
                //         t2 = null; // 1
                Diagnostic(ErrorCode.WRN_ConvertingNullableToNonNullable, "null").WithLocation(14, 14),
                // (21,9): warning CS8602: Dereference of a possibly null reference.
                //         xOpen.f1.ToString(); // 2
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "xOpen.f1").WithLocation(21, 9),
                // (25,9): warning CS8602: Dereference of a possibly null reference.
                //         xClass.f2.ToString(); // 3
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "xClass.f2").WithLocation(25, 9),
                // (27,9): warning CS8602: Dereference of a possibly null reference.
                //         xClass.f3.ToString(); // 4
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "xClass.f3").WithLocation(27, 9)
            };

            var comp = CreateNullableCompilation(new[] { source, MaybeNullAttributeDefinition }, references: new[] { lib.EmitToImageReference() });
            comp.VerifyDiagnostics(expected);

            var comp2 = CreateNullableCompilation(new[] { source, lib_cs, AllowNullAttributeDefinition, MaybeNullAttributeDefinition });
            comp2.VerifyDiagnostics(expected);

            CompileAndVerify(comp2, sourceSymbolValidator: symbolValidator, symbolValidator: symbolValidator);

            void symbolValidator(ModuleSymbol m)
            {
                bool isSource = !(m is PEModuleSymbol);
                var copen = (NamedTypeSymbol)m.GlobalNamespace.GetMember("COpen");
                var field = copen.GetMembers().OfType<FieldSymbol>().Single();

                var fieldAttributes = field.GetAttributes().Select(a => a.ToString());
                if (isSource)
                {
                    AssertEx.Equal(new[] { "System.Diagnostics.CodeAnalysis.AllowNullAttribute" }, fieldAttributes);
                }
                else
                {
                    AssertEx.Equal(new[] { "System.Runtime.CompilerServices.NullableAttribute(1)", "System.Diagnostics.CodeAnalysis.AllowNullAttribute" }, fieldAttributes);
                }
            }
        }

