        [Fact]
        public void AllowNull_01_Indexer()
        {
            // Warn on misused nullability attributes? https://github.com/dotnet/roslyn/issues/36073
            var lib_cs =
@"using System.Diagnostics.CodeAnalysis;
public class COpen<TOpen>
{
    [AllowNull]public TOpen this[int i] { set => throw null!; }
}
public class CClass<TClass> where TClass : class
{
    [AllowNull]public TClass this[int i] { set => throw null!; }
}
public class CClass2<TClass> where TClass : class
{
    [AllowNull]public TClass? this[int i] { set => throw null!; }
}
public class CStruct<TStruct> where TStruct : struct
{
    [AllowNull]public TStruct this[int i] { set => throw null!; }
}
public class CStruct2<TStruct> where TStruct : struct
{
    [AllowNull]public TStruct? this[int i] { set => throw null!; }
}";
            var lib = CreateNullableCompilation(new[] { lib_cs, AllowNullAttributeDefinition });

            var source = @"
class Program
{
    static void M1<T>(T t1)
    {
        new COpen<T>()[0] = t1;
    }
    static void M2<T>(T t2) where T : class
    {
        new COpen<T>()[0] = t2;
        new CClass<T>()[0] = t2;
        new CClass2<T>()[0] = t2;
        t2 = null; // 1
        new COpen<T>()[0] = t2;
        new CClass<T>()[0] = t2;
        new CClass2<T>()[0] = t2;
    }
    static void M3<T>(T? t3) where T : class
    {
        new COpen<T>()[0] = t3;
        new CClass<T>()[0] = t3;
        new CClass2<T>()[0] = t3;
        if (t3 == null) return;
        new COpen<T>()[0] = t3;
        new CClass<T>()[0] = t3;
        new CClass2<T>()[0] = t3;
    }
    static void M4<T>(T t4) where T : struct
    {
        new COpen<T>()[0] = t4;
        new CStruct<T>()[0] = t4;
    }
    static void M5<T>(T? t5) where T : struct
    {
        new COpen<T?>()[0] = t5;
        new CStruct2<T>()[0] = t5;
        if (t5 == null) return;
        new COpen<T?>()[0] = t5;
        new CStruct2<T>()[0] = t5;
    }
}";

            var expected = new[]
            {
                // (13,14): warning CS8600: Converting null literal or possible null value to non-nullable type.
                //         t2 = null; // 1
                Diagnostic(ErrorCode.WRN_ConvertingNullableToNonNullable, "null").WithLocation(13, 14)
            };

            var comp = CreateNullableCompilation(source, references: new[] { lib.EmitToImageReference() });
            comp.VerifyDiagnostics(expected);

            var comp2 = CreateNullableCompilation(new[] { source, lib_cs, AllowNullAttributeDefinition });
            comp2.VerifyDiagnostics(expected);

            CompileAndVerify(comp2, sourceSymbolValidator: symbolValidator, symbolValidator: symbolValidator);

            void symbolValidator(ModuleSymbol m)
            {
                bool isSource = !(m is PEModuleSymbol);
                var copen = (NamedTypeSymbol)m.GlobalNamespace.GetMember("COpen");
                var copenAttributes = copen.GetAttributes().Select(a => a.ToString());
                if (isSource)
                {
                    AssertEx.Empty(copenAttributes);
                }
                else
                {
                    AssertEx.Equal(new[] { "System.Runtime.CompilerServices.NullableContextAttribute(1)", "System.Runtime.CompilerServices.NullableAttribute(0)", "System.Reflection.DefaultMemberAttribute(\"Item\")" }, copenAttributes);
                }

                var property = copen.GetMembers().OfType<PropertySymbol>().Single();
                var propertyAttributes = property.GetAttributes().Select(a => a.ToString());
                if (isSource)
                {
                    AssertEx.Equal(new[] { "System.Diagnostics.CodeAnalysis.AllowNullAttribute" }, propertyAttributes);
                }
                else
                {
                    AssertEx.Empty(propertyAttributes);
                }

                var setter = property.SetMethod;
                var setterAttributes = setter.GetAttributes();
                AssertEx.Empty(setterAttributes);

                var setterValueAttributes = setter.Parameters.Last().GetAttributes().Select(a => a.ToString());
                Assert.Equal(FlowAnalysisAnnotations.AllowNull, setter.Parameters.Last().FlowAnalysisAnnotations);
                if (isSource)
                {
                    AssertEx.Empty(setterValueAttributes);
                }
                else
                {
                    AssertEx.Equal(new[] { "System.Diagnostics.CodeAnalysis.AllowNullAttribute" }, setterValueAttributes);
                }

                Assert.Equal(FlowAnalysisAnnotations.None, setter.ReturnTypeFlowAnalysisAnnotations);
                var setterReturnAttributes = setter.GetReturnTypeAttributes();
                AssertEx.Empty(setterReturnAttributes);
            }
        }

