            comp.VerifyDiagnostics();

            CompileAndVerify(comp, sourceSymbolValidator: symbolValidator, symbolValidator: symbolValidator);

            void symbolValidator(ModuleSymbol m)
            {
                bool isSource = !(m is PEModuleSymbol);
                var copen = (NamedTypeSymbol)m.GlobalNamespace.GetMember("COpen");
                var copenAttributes = copen.GetAttributes().Select(a => a.ToString());
                if (isSource)
                {
                    AssertEx.Empty(copenAttributes);
                }
                else
                {
                    AssertEx.Equal(new[] { "System.Runtime.CompilerServices.NullableContextAttribute(1)", "System.Runtime.CompilerServices.NullableAttribute(0)", "System.Reflection.DefaultMemberAttribute(\"Item\")" }, copenAttributes);
                }

                var property = copen.GetMembers().OfType<PropertySymbol>().Single();
                var propertyAttributes = property.GetAttributes().Select(a => a.ToString());
                if (isSource)
                {
                    AssertEx.Equal(new[] { "System.Diagnostics.CodeAnalysis.AllowNullAttribute", "System.Diagnostics.CodeAnalysis.DisallowNullAttribute" }, propertyAttributes);
                }
                else
                {
                    AssertEx.Empty(propertyAttributes);
                }

                var setter = property.SetMethod;
                var setterAttributes = setter.GetAttributes();
                AssertEx.Empty(setterAttributes);

                var setterValueAttributes = setter.Parameters.Last().GetAttributes().Select(a => a.ToString());
                Assert.Equal(FlowAnalysisAnnotations.AllowNull | FlowAnalysisAnnotations.DisallowNull, setter.Parameters.Last().FlowAnalysisAnnotations);
                if (isSource)
                {
                    AssertEx.Empty(setterValueAttributes);
                }
                else
                {
                    AssertEx.Equal(new[] {
                        "System.Diagnostics.CodeAnalysis.DisallowNullAttribute",
                        "System.Diagnostics.CodeAnalysis.AllowNullAttribute" }, setterValueAttributes);
                }
            }
        }

