    public virtual void F5<T>([AllowNull]T? t1, [AllowNull] out T? t2, [AllowNull] ref T? t3, [AllowNull] in T? t4) where T : struct => throw null!;
}
public class Derived : Base
{
    public override void F1<T>(T  t1, out T  t2, ref T  t3, in T  t4)                  => throw null!; // t1, t3, t4
    public override void F2<T>(T  t1, out T  t2, ref T  t3, in T  t4) where T : class  => throw null!; // t1, t3, t4
    public override void F3<T>(T? t1, out T? t2, ref T? t3, in T? t4) where T : class  => throw null!;
