        public void DisallowNullInputParam_UpdatesArgumentState()
        {
            var source = @"
#nullable enable
using System.Diagnostics.CodeAnalysis;

class C
{
    void M1(int? x)
    {
        C c = x; // 1
        Method(x);
    }

    void M2(int? x)
    {
        Method(x); // 2
        C c = x;
    }

    void Method([DisallowNull] int? t) { }

    public static implicit operator C([DisallowNull] int? s) => new C();
}
";
            var comp = CreateNullableCompilation(new[] { source, DisallowNullAttributeDefinition });
            comp.VerifyDiagnostics(
                // (9,15): warning CS8607: A possible null value may not be used for a type marked with [NotNull] or [DisallowNull]
                //         C c = x; // 1
                Diagnostic(ErrorCode.WRN_DisallowNullAttributeForbidsMaybeNullAssignment, "x").WithLocation(9, 15),
                // (15,16): warning CS8607: A possible null value may not be used for a type marked with [NotNull] or [DisallowNull]
                //         Method(x); // 2
                Diagnostic(ErrorCode.WRN_DisallowNullAttributeForbidsMaybeNullAssignment, "x").WithLocation(15, 16));
        }

