        [WorkItem(39922, "https://github.com/dotnet/roslyn/issues/39922")]
        public void EnforcedInMethodBody_NotNullWhen_Composition(string type)
        {
            var source = @"
#nullable enable

using System.Diagnostics.CodeAnalysis;

class C<TStruct, TClass>
    where TStruct : struct
    where TClass : class
{
    static bool TryGetValue([NotNullWhen(true)] out TYPE y)
    {
        return TryGetValue(out y);
    }

    static bool TryGetValue2([NotNullWhen(true)] out TYPE y)
    {
        return TryGetValue3(out y); // 1
    }

    static bool TryGetValue3([NotNullWhen(false)] out TYPE y)
    {
        return TryGetValue3(out y);
    }

    static bool TryGetValue3B([NotNullWhen(false)] out TYPE y)
    {
        return TryGetValue2(out y); // 2
    }

    static bool TryGetValue4([NotNull] TYPE x, [NotNullWhen(false)] out TYPE y)
    {
        return TryGetValue4(x, out y);
    }

    static bool TryGetValueString1(string key, [MaybeNullWhen(false)] out string value)
        => TryGetValueString2(key, out value);
    static bool TryGetValueString2(string key, [NotNullWhen(true)] out string? value)
        => TryGetValueString1(key, out value);
}
";
            var comp = CreateNullableCompilation(new[] { MaybeNullWhenAttributeDefinition, NotNullAttributeDefinition, NotNullWhenAttributeDefinition, source.Replace("TYPE", type) });
            comp.VerifyDiagnostics(
                // (17,9): warning CS8762: Parameter 'y' must have a non-null value when exiting with 'true'.
                //         return TryGetValue3(out y); // 1
                Diagnostic(ErrorCode.WRN_ParameterConditionallyDisallowsNull, "return TryGetValue3(out y);").WithArguments("y", "true").WithLocation(17, 9),
                // (27,9): warning CS8762: Parameter 'y' must have a non-null value when exiting with 'false'.
                //         return TryGetValue2(out y); // 2
                Diagnostic(ErrorCode.WRN_ParameterConditionallyDisallowsNull, "return TryGetValue2(out y);").WithArguments("y", "false").WithLocation(27, 9)
                );
        }

