        [Fact, WorkItem(39922, "https://github.com/dotnet/roslyn/issues/39922")]
        public void EnforcedInMethodBody_DoesNotReturn()
        {
            var source = @"
#nullable enable
using System.Diagnostics.CodeAnalysis;
class C
{
    [DoesNotReturn]
    static void ActuallyReturns()
    {
    } // 1

    [DoesNotReturn]
    static bool ActuallyReturns2()
    {
        return true; // 2
    }

    [DoesNotReturn]
    static bool ActuallyReturns3(bool b)
    {
        if (b)
            throw null!;
        else
            return true; // 3
    }

    [DoesNotReturn]
    static bool ActuallyReturns4()
        => true; // 4

    [DoesNotReturn]
    static void NeverReturns()
    {
        throw null!;
    }

    [DoesNotReturn]
    static bool NeverReturns2()
    {
        throw null!;
    }

    [DoesNotReturn]
    static bool NeverReturns3()
        => throw null!;

    [DoesNotReturn]
    static bool NeverReturns4()
    {
        return NeverReturns2();
    }

    [DoesNotReturn]
    static void NeverReturns5()
    {
        NeverReturns();
    }

    [DoesNotReturn]
    static void NeverReturns6()
    {
        while (true) { }
    }
}
";
