                // (14,9): error CS8763: A method marked [DoesNotReturn] should not return.
                //         return true; // 2
                Diagnostic(ErrorCode.WRN_ShouldNotReturn, "return true;").WithLocation(14, 9),
                // (23,13): error CS8763: A method marked [DoesNotReturn] should not return.
                //             return true; // 3
                Diagnostic(ErrorCode.WRN_ShouldNotReturn, "return true;").WithLocation(23, 13),
                // (28,12): error CS8763: A method marked [DoesNotReturn] should not return.
                //         => true; // 4
                Diagnostic(ErrorCode.WRN_ShouldNotReturn, "true").WithLocation(28, 12)
                );
        }

