        [Fact, WorkItem(39922, "https://github.com/dotnet/roslyn/issues/39922")]
        public void DoesNotReturn_OHI()
        {
            var source = @"
#nullable enable
using System.Diagnostics.CodeAnalysis;
public class Base
{
    [DoesNotReturn]
    public virtual void M() => throw null!;
}
public class Derived : Base
{
    public override void M() => throw null!; // 1
}
public class Derived2 : Base
{
    [DoesNotReturn]
    public override void M() => throw null!;
}
public class Derived3 : Base
{
    [DoesNotReturn]
    public new void M() => throw null!;
}
public class Derived4 : Base
{
    public new void M() => throw null!;
}

interface I
{
    [DoesNotReturn]
    bool M();
}
class C1 : I
{
    bool I.M() => throw null!; // 2
}
class C2 : I
{
    [DoesNotReturn]
    bool I.M() => throw null!;
}
";
            var comp = CreateNullableCompilation(new[] { DoesNotReturnAttributeDefinition, DoesNotReturnIfAttributeDefinition, source });
            comp.VerifyDiagnostics(
                // (11,26): warning CS8770: Method 'void Derived.M()' lacks `[DoesNotReturn]` annotation to match implemented or overridden member.
                //     public override void M() => throw null!; // 1
                Diagnostic(ErrorCode.WRN_DoesNotReturnMismatch, "M").WithArguments("void Derived.M()").WithLocation(11, 26),
                // (35,12): warning CS8770: Method 'bool C1.M()' lacks `[DoesNotReturn]` annotation to match implemented or overridden member.
                //     bool I.M() => throw null!; // 2
                Diagnostic(ErrorCode.WRN_DoesNotReturnMismatch, "M").WithArguments("bool C1.M()").WithLocation(35, 12)
                );
        }

