    public virtual void F4<T>([MaybeNull]T  t1, [MaybeNull] out T  t2, [MaybeNull] ref T  t3, [MaybeNull] in T  t4) where T : struct => throw null!;
    public virtual void F5<T>([MaybeNull]T? t1, [MaybeNull] out T? t2, [MaybeNull] ref T? t3, [MaybeNull] in T? t4) where T : struct => throw null!;
    public virtual void F6<T>([MaybeNull]T  t1, [MaybeNull] out T  t2, [MaybeNull] ref T  t3, [MaybeNull] in T  t4) where T : notnull => throw null!;
}
public class Derived : Base
{
    public override void F1<T>(T  t1, out T  t2, ref T  t3, in T  t4)                  => throw null!; // t1, t4
    public override void F2<T>(T  t1, out T  t2, ref T  t3, in T  t4) where T : class  => throw null!; // t1, t4
