        [Fact]
        public void MaybeNullWhenTrue_ImplementingAnnotatedInterface()
        {
            var source =
@"using System.Diagnostics.CodeAnalysis;
#nullable disable
public interface I<T>
{
    bool TryGetValue(out T t);
}

#nullable enable
public class C<T> : I<T>
{
    public bool TryGetValue([MaybeNullWhen(false)] out T t) => throw null!;
}
";
            // Note: because we're implementing `I<T!>!`, we complain about returning a possible null value
            // through `bool TryGetValue(out T! t)`
            var comp = CreateCompilation(new[] { MaybeNullWhenAttributeDefinition, source });
            comp.VerifyDiagnostics(
                // (11,17): warning CS8767: Nullability of reference types in type of parameter 't' of 'bool C<T>.TryGetValue(out T t)' doesn't match implicitly implemented member 'bool I<T>.TryGetValue(out T t)' because of nullability attributes.
                //     public bool TryGetValue([MaybeNullWhen(false)] out T t) => throw null!;
                Diagnostic(ErrorCode.WRN_TopLevelNullabilityMismatchInParameterTypeOnImplicitImplementation, "TryGetValue").WithArguments("t", "bool C<T>.TryGetValue(out T t)", "bool I<T>.TryGetValue(out T t)").WithLocation(11, 17)
                );
        }

