            var lib_cs =
@"using System.Diagnostics.CodeAnalysis;
public class COpen<TOpen>
{
    [DisallowNull]public TOpen P1 { get; set; } = default!;
}
public class CClass<TClass> where TClass : class
{
    [DisallowNull]public TClass P2 { get; set; } = null!;
    [DisallowNull]public TClass? P3 { get; set; } = null;
}
public class CStruct<TStruct> where TStruct : struct
{
    [DisallowNull]public TStruct P4 { get; set; }
    [DisallowNull]public TStruct? P5 { get; set; }
}
";

            var lib = CreateNullableCompilation(new[] { DisallowNullAttributeDefinition, lib_cs });

            var source = @"
class C
{
    static void M1<T>(T t1)
    {
        new COpen<T>().P1 = t1; // 0
    }
    static void M2<T>(T t2) where T : class
    {
        new COpen<T>().P1 = t2;
        new CClass<T>().P2 = t2;
        new CClass<T>().P3 = t2;
        t2 = null; // 1
        new COpen<T>().P1 = t2; // 2
        new CClass<T>().P2 = t2; // 3
        new CClass<T>().P3 = t2; // 4, [DisallowNull] honored on TClass?
    }
    static void M3<T>(T? t3) where T : class
    {
        new COpen<T>().P1 = t3; // 5
        new CClass<T>().P2 = t3; // 6
        new CClass<T>().P3 = t3; // 7, [DisallowNull] honored on TClass?
        if (t3 == null) return;
        new COpen<T>().P1 = t3;
