        Property += c; // 1
        Property.ToString(); // 2 - operator result may be null, so we have maybe-null flow state for LHS here.
    }
}
struct S
{
    S? Property { get { throw null!; } set { throw null!; } }
    public static S? operator+([DisallowNull] S? one, S other) => throw null!;

