                Diagnostic(ErrorCode.WRN_NullReferenceAssignment, "t3").WithLocation(35, 30),
                // (36,30): warning CS8601: Possible null reference assignment.
                //         new CClass<T>().P3 = t3; // 7, [DisallowNull] honored on TClass?
