        [Fact]
        public void MaybeNull_WithNotNull()
        {
            var source =
@"using System.Diagnostics.CodeAnalysis;
internal class C<T> where T : class?
{
    public bool F([MaybeNull, NotNull] out T target) => throw null!;
    [return: MaybeNull, NotNull] public T F2() => throw null!;

    public string Method(C<string> wr)
    {
        if (!wr.F(out string? s))
        {
            s = """";
        }
        return s; // 1
    }
    public string Method2(C<string> wr, bool b)
    {
        var s = wr.F2();
        if (b)
            return s; // 2
        s = null;
        throw null!;
    }
}";
            // MaybeNull wins over NotNull
            var comp = CreateNullableCompilation(new[] { MaybeNullAttributeDefinition, NotNullAttributeDefinition, source });
            comp.VerifyDiagnostics(
                // (13,16): warning CS8603: Possible null reference return.
                //         return s; // 1
                Diagnostic(ErrorCode.WRN_NullReferenceReturn, "s").WithLocation(13, 16),
                // (19,20): warning CS8603: Possible null reference return.
                //             return s; // 2
                Diagnostic(ErrorCode.WRN_NullReferenceReturn, "s").WithLocation(19, 20)
