            // Warn on misused nullability attributes (F2, F3, F4 and probably F5)? https://github.com/dotnet/roslyn/issues/36073
            var source =
@"using System.Diagnostics.CodeAnalysis;
class Program
{
    static void F1<T>(T t, [MaybeNull]out T t2) { t2 = t; }
    static void F2<T>(T t, [MaybeNull]out T t2) where T : class { t2 = t; }
    static void F3<T>(T t, [MaybeNull]out T? t2) where T : class { t2 = t; }
    static void F4<T>(T t, [MaybeNull]out T t2) where T : struct { t2 = t; }
    static void F5<T>(T? t, [MaybeNull]out T? t2) where T : struct { t2 = t; }
    static void M1<T>(T t1)
    {
        F1(t1, out var s2); // 0
        s2.ToString(); // 1
    }
    static void M2<T>(T t2) where T : class
    {
        F1(t2, out var s3);
        s3.ToString(); // 2

        F2(t2, out var s4);
        s4.ToString(); // 3

        F3(t2, out var s5);
        s5.ToString(); // 4

        t2 = null; // 5
        F1(t2, out var s6);
        s6.ToString(); // 6

        F2(t2, out var s7); // 7
        s7.ToString(); // 8

        F3(t2, out var s8); // 9
        s8.ToString(); // 10
    }
    static void M3<T>(T? t3) where T : class
    {
        F1(t3, out var s9);
        s9.ToString(); // 11

        F2(t3, out var s10); // 12
        s10.ToString(); // 13

        F3(t3, out var s11); // 14
        s11.ToString(); // 15

        if (t3 == null) return;
        F1(t3, out var s12);
        s12.ToString(); // 16

        F2(t3, out var s13);
        s13.ToString(); // 17

        F3(t3, out var s14);
        s14.ToString(); // 18
    }
    static void M4<T>(T t4) where T : struct
    {
        F1(t4, out var s15);
        s15.ToString();

        F4(t4, out var s16);
        s16.ToString();
    }
    static void M5<T>(T? t5) where T : struct
    {
        F1(t5, out var s17);
        _ = s17.Value; // 19

        F5(t5, out var s18);
        _ = s18.Value; // 20

        if (t5 == null) return;
        F1(t5, out var s19);
        _ = s19.Value; // 21

        F5(t5, out var s20);
        _ = s20.Value; // 22
    }
}";
