        s3.ToString(); // 3

        F3<T>(t2, out var s4);
        s4.ToString(); // 4

        t2 = null; // 5
        F1<T>(b ? t2 : default, out var s5); // 6
        s5.ToString(); // 6B

        F2<T>(b ? t2 : default, out var s6); // 7
