            var source =
@"using System.Diagnostics.CodeAnalysis;
class Program
{
    static void F1([MaybeNull]out string t) => throw null!;
    static void F2([MaybeNull]out string? t) => throw null!;
    static void M()
    {
        F1(out var t1);
        t1.ToString(); // 1

        F2(out var t2);
        t2.ToString(); // 2
    }
}";
