@"using System.Diagnostics.CodeAnalysis;
class Program
{
    static void F1<T>(T t, [MaybeNull]ref T t2) { t2 = t; }
    static void F2<T>(T t, [MaybeNull]ref T t2) where T : class { t2 = t; }
    static void F3<T>(T t, [MaybeNull]ref T? t2) where T : class { t2 = t; }
    static void F4<T>(T t, [MaybeNull]ref T t2) where T : struct { t2 = t; }
    static void F5<T>(T? t, [MaybeNull]ref T? t2) where T : struct { t2 = t; }
    static void M1<T>(T t1)
    {
        T s2 = default!;
        F1(t1, ref s2); // 0
        s2.ToString(); // 1
    }
    static void M2<T>(T t2) where T : class
    {
        T? s3 = default!;
        F1(t2, ref s3);
        s3.ToString(); // 2

        T s4 = default!;
        F2(t2, ref s4); // 3
        s4.ToString(); // 4

        T s4b = default!;
        F2(t2, ref s4b!); // suppression applies after MaybeNull
        s4b.ToString();

        T? s5 = default!;
        F3(t2, ref s5);
        s5.ToString(); // 5

        t2 = null; // 6
        T? s6 = default!;
        F1(t2, ref s6);
        s6.ToString(); // 7

        T? s7 = default!;
        F2(t2, ref s7); // 8
        s7.ToString(); // 9

        T? s8 = default!;
        F3(t2, ref s8); // 10
        s8.ToString(); // 11
    }
    static void M3<T>(T? t3) where T : class
    {
        T? s9 = default!;
        F1(t3, ref s9);
        s9.ToString(); // 12

        T s10 = default!;
        F2(t3, ref s10); // 13, 14
        s10.ToString(); // 15

        T? s11 = default!;
        F3(t3, ref s11); // 16
        s11.ToString(); // 17

        if (t3 == null) return;
        T s12 = default!;
        F1(t3, ref s12); // 18
        s12.ToString(); // 19

        T s13 = default!;
        F2(t3, ref s13); // 20
        s13.ToString(); // 21

        T? s14 = default!;
        F3(t3, ref s14);
        s14.ToString(); // 22
    }
    static void M4<T>(T t4) where T : struct
    {
        T s15 = default;
        F1(t4, ref s15);
        s15.ToString();

        T s16 = default;
        F4(t4, ref s16);
        s16.ToString();
    }
    static void M5<T>(T? t5) where T : struct
    {
        T s17 = default!;
        F1(t5, ref s17); // 23
        _ = s17.Value; // 24

        T s18 = default!;
        F5(t5, ref s18); // 25
        _ = s18.Value; // 26

        if (t5 == null) return;
        T s19 = default!;
        F1(t5, ref s19); // 27
        _ = s19.Value; // 28

        T s20 = default!;
        F5(t5, ref s20); // 29
        _ = s20.Value; // 30
    }
}";
