class Program
{
    [return: NotNull] static T F1<T>(T t) => t; // 00
    [return: NotNull] static T F2<T>(T t) where T : class => t;
    [return: NotNull] static T? F3<T>(T t) where T : class => t;
    [return: NotNull] static T F4<T>(T t) where T : struct => t;
    [return: NotNull] static T? F5<T>(T? t) where T : struct => t; // 0
    static void M1<T>(T t1)
    {
        F1(t1).ToString();
    }
    static void M2<T>(T t2) where T : class
    {
        F1(t2).ToString();
        F2(t2).ToString();
        F3(t2).ToString();
        t2 = null; // 1
        F1(t2).ToString();
        F2(t2).ToString(); // 2
        F3(t2).ToString(); // 3
    }
    static void M3<T>(T? t3) where T : class
    {
        F1(t3).ToString();
        F2(t3).ToString(); // 4
        F3(t3).ToString(); // 5
