using System.Diagnostics.CodeAnalysis;
public class Base
{
    [NotNull] public virtual string? P => throw null!;
    public virtual string? P2 => throw null!;
}
public class C : Base
{
    public override string? P => throw null!; // 0
    [NotNull] public override string? P2 => throw null!;

    static void M(C c, Base b)
    {
        b.P.ToString();
        c.P.ToString(); // 1

        b.P2.ToString(); // 2
        c.P2.ToString();
    }
}";
