                Diagnostic(ErrorCode.WRN_TopLevelNullabilityMismatchInReturnTypeOnOverride, "throw null!").WithLocation(10, 34),
                // (16,9): warning CS8602: Dereference of a possibly null reference.
                //         c.P.ToString(); // 1
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "c.P").WithLocation(16, 9),
                // (18,9): warning CS8602: Dereference of a possibly null reference.
                //         b.P2.ToString(); // 2
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "b.P2").WithLocation(18, 9)
                );
        }

