class C
{
    const bool FIELD_TRUE = true;
    const bool FIELD_FALSE = false;

    static void M(bool b, object? x)
    {
        const bool LOCAL_TRUE = true;
        const bool LOCAL_FALSE = false;

        x = null;
        _ = (b ? x != null : " + @false + @")  // `b && x != null`
            ? x.ToString()
            : x.ToString(); // 1

        x = new object();
        _ = (b ? x != null : " + @false + @")  // `b && x != null`
            ? x.ToString()
            : x.ToString(); // 2


        x = null;
        _ = (b ? x != null : " + @true + @")  // `!b || x != null`
            ? x.ToString() // 3
            : x.ToString(); // 4

        x = new object();
        _ = (b ? x != null : " + @true + @")  // `!b || x != null`
            ? x.ToString()
            : x.ToString(); // 5


        x = null;
        _ = (b ? " + @false + @" : x != null)  // `!b && x != null`
            ? x.ToString()
            : x.ToString(); // 6

        x = new object();
        _ = (b ? " + @false + @" : x != null)  // `!b && x != null`
            ? x.ToString()
            : x.ToString(); // 7


        x = null;
        _ = (b ? " + @true + @" : x != null)  // `b || x != null`
            ? x.ToString() // 8
            : x.ToString(); // 9

        x = new object();
        _ = (b ? " + @true + @" : x != null)  // `b || x != null`
            ? x.ToString()
            : x.ToString(); // 10


        x = null;
        _ = !(b ? " + @true + @" : x != null)  // `!(b || x != null)` -> `!b && x == null`
            ? x.ToString() // 11
            : x.ToString(); // 12

        x = new object();
        _ = !(b ? " + @true + @" : x != null)  // `!(b || x != null)` -> `!b && x == null`
            ? x.ToString() // 13
            : x.ToString();
    }
}
