        [Fact]
        public void ConditionalOperator_15()
        {
            // We likely shouldn't be warning on the x[0] access, as code is an error. However, we currently do
            // because of fallout from https://github.com/dotnet/roslyn/issues/34158: when we calculate the
            // type of new[] { x }, the type of the BoundLocal x is ErrorType var, but the type of the local
            // symbol is ErrorType var[]. VisitLocal prefers the type of the BoundLocal, and so the
            // new[] { x } expression is calculated to have a final type of ErrorType var[]. The default is
            // target typed to ErrorType var[] as well, and the logic in VisitConditionalOperator therefore
            // uses that type as the final type of the expression. This calculation succeeded, so that result
            // is stored as the current nullability of x, causing us to warn on the subsequent line.
            var source =
@"class Program
{
    static void F(bool b)
    {
        var x = b ? new[] { x } : default;
        x[0].ToString();
    }
}";
            var comp = CreateCompilation(source, options: WithNullableEnable());
            comp.VerifyDiagnostics(
                // (5,29): error CS0841: Cannot use local variable 'x' before it is declared
                //         var x = b ? new[] { x } : default;
                Diagnostic(ErrorCode.ERR_VariableUsedBeforeDeclaration, "x").WithArguments("x").WithLocation(5, 29),
                // (6,9): warning CS8602: Dereference of a possibly null reference.
                //         x[0].ToString();
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "x").WithLocation(6, 9));
        }

        [Fact]
        public void ConditionalOperator_16()
        {
            var source =
@"class Program
{
    static bool F(object? x)
    {
        return true;
    }
    static void F1(bool b, bool c, object x1, object? y1)
    {
        if (b ? c && F(x1 = y1) : true) // 1
        {
            x1.ToString(); // 2
        }
    }
    static void F2(bool b, bool c, object x2, object? y2)
    {
        if (b ? true : c && F(x2 = y2)) // 3
        {
            x2.ToString(); // 4
        }
    }
}";
            var comp = CreateCompilation(source, options: WithNullableEnable());
            comp.VerifyDiagnostics(
                // (9,29): warning CS8600: Converting null literal or possible null value to non-nullable type.
                //         if (b ? c && F(x1 = y1) : true) // 1
                Diagnostic(ErrorCode.WRN_ConvertingNullableToNonNullable, "y1").WithLocation(9, 29),
                // (11,13): warning CS8602: Dereference of a possibly null reference.
                //             x1.ToString(); // 2
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "x1").WithLocation(11, 13),
                // (16,36): warning CS8600: Converting null literal or possible null value to non-nullable type.
                //         if (b ? true : c && F(x2 = y2)) // 3
                Diagnostic(ErrorCode.WRN_ConvertingNullableToNonNullable, "y2").WithLocation(16, 36),
                // (18,13): warning CS8602: Dereference of a possibly null reference.
                //             x2.ToString(); // 4
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "x2").WithLocation(18, 13));
        }

