        [Fact, WorkItem(33664, "https://github.com/dotnet/roslyn/issues/33664")]
        public void ConditionalOperator_AssigningToRefConditional()
        {
            var source0 =
@"public class A
{
    public static string F;
}";
            var comp0 = CreateCompilation(source0, parseOptions: TestOptions.Regular7);
            comp0.VerifyDiagnostics();
            var ref0 = comp0.EmitToImageReference();

            var comp = CreateCompilation(@"
class C
{
    void M(bool c, ref string x, ref string? y)
    {
        (c ? ref x : ref y) = null; // 1, 2
    }
    void M2(bool c, ref string x, ref string? y)
    {
        (c ? ref y : ref x) = null; // 3, 4
    }
    void M3(bool c, ref string x, ref string? y)
    {
        (c ? ref x : ref A.F) = null; // 5
        (c ? ref y : ref A.F) = null;
    }
    void M4(bool c, ref string x, ref string? y)
    {
        (c ? ref A.F : ref x) = null; // 6
        (c ? ref A.F : ref y) = null;
    }
}", options: WithNullableEnable(), references: new[] { ref0 });

            comp.VerifyDiagnostics(
                // (6,26): warning CS8619: Nullability of reference types in value of type 'string?' doesn't match target type 'string'.
                //         (c ? ref x : ref y) = null; // 1, 2
                Diagnostic(ErrorCode.WRN_NullabilityMismatchInAssignment, "y").WithArguments("string?", "string").WithLocation(6, 26),
                // (6,31): warning CS8625: Cannot convert null literal to non-nullable reference type.
                //         (c ? ref x : ref y) = null; // 1, 2
                Diagnostic(ErrorCode.WRN_NullAsNonNullable, "null").WithLocation(6, 31),
                // (10,18): warning CS8619: Nullability of reference types in value of type 'string?' doesn't match target type 'string'.
                //         (c ? ref y : ref x) = null; // 3, 4
                Diagnostic(ErrorCode.WRN_NullabilityMismatchInAssignment, "y").WithArguments("string?", "string").WithLocation(10, 18),
                // (10,31): warning CS8625: Cannot convert null literal to non-nullable reference type.
                //         (c ? ref y : ref x) = null; // 3, 4
                Diagnostic(ErrorCode.WRN_NullAsNonNullable, "null").WithLocation(10, 31),
                // (14,33): warning CS8625: Cannot convert null literal to non-nullable reference type.
                //         (c ? ref x : ref A.F) = null; // 5
                Diagnostic(ErrorCode.WRN_NullAsNonNullable, "null").WithLocation(14, 33),
                // (19,33): warning CS8625: Cannot convert null literal to non-nullable reference type.
                //         (c ? ref A.F : ref x) = null; // 6
                Diagnostic(ErrorCode.WRN_NullAsNonNullable, "null").WithLocation(19, 33)
                );
        }

        [Fact]
        public void IdentityConversion_ConditionalOperator()
        {
            var source =
@"interface I<T> { }
interface IIn<in T> { }
interface IOut<out T> { }
class C
{
    static void F(bool c, I<object> x, I<object?> y)
    {
        I<object> a;
        a = c ? x : y;
        a = false ? x : y;
        a = true ? x : y; // ok
        I<object?> b;
        b = c ? x : y;
        b = false ? x : y;
        b = true ? x : y;
    }
    static void F(bool c, IIn<object> x, IIn<object?> y)
    {
        IIn<object> a;
        a = c ? x : y;
        a = false ? x : y;
        a = true ? x : y;
        IIn<object?> b;
        b = c ? x : y;
        b = false ? x : y;
        b = true ? x : y;
    }
    static void F(bool c, IOut<object> x, IOut<object?> y)
    {
        IOut<object> a;
        a = c ? x : y;
        a = false ? x : y;
        a = true ? x : y;
        IOut<object?> b;
        b = c ? x : y;
        b = false ? x : y;
        b = true ? x : y;
    }
}";
            var comp = CreateCompilation(new[] { source }, options: WithNullableEnable());
            comp.VerifyDiagnostics(
                // (9,21): warning CS8619: Nullability of reference types in value of type 'I<object?>' doesn't match target type 'I<object>'.
                //         a = c ? x : y;
