                break;
            case 3:
                (null ?? y1)/*T:Unknown?*/.ToString();
                break;
            case 4:
                (y1 ?? null)/*T:Unknown!*/.ToString();
                break;
        }
    }
    static void F2(int i, C? x2, Unknown y2)
    {
        switch (i)
        {
            case 1:
                (x2 ?? y2)/*T:!*/.ToString();
                break;
            case 2:
                (y2 ?? x2)/*T:!*/.ToString();
                break;
            case 3:
                (null ?? y2)/*T:!*/.ToString();
                break;
            case 4:
                (y2 ?? null)/*T:!*/.ToString();
                break;
        }
    }
}";
