                new[] { source }, options: WithNullableEnable(),
                parseOptions: TestOptions.Regular8);
            comp.VerifyDiagnostics(
                // (5,17): error CS0841: Cannot use local variable 's' before it is declared
                //         var s = s;
                Diagnostic(ErrorCode.ERR_VariableUsedBeforeDeclaration, "s").WithArguments("s").WithLocation(5, 17));

            var tree = comp.SyntaxTrees[0];
            var model = comp.GetSemanticModel(tree);
            var declarator = tree.GetRoot().DescendantNodes().OfType<VariableDeclaratorSyntax>().First();
            var symbol = model.GetDeclaredSymbol(declarator).GetSymbol<LocalSymbol>();
            var type = symbol.TypeWithAnnotations;
            Assert.True(type.Type.IsErrorType());
            Assert.Equal("var?", type.ToTestDisplayString());
            Assert.Equal(NullableAnnotation.Annotated, type.NullableAnnotation);
        }

        [Fact]
        public void Var_ConditionalOperator()
        {
            var source =
@"class C
{
    static void F(bool b, string s)
    {
        var s0 = b ? s : s;
        var s1 = b ? s : null;
        var s2 = b ? null : s;
    }
}";

            var comp = CreateCompilation(
                new[] { source }, options: WithNullableEnable(),
                parseOptions: TestOptions.Regular8);
            comp.VerifyDiagnostics();

            var tree = comp.SyntaxTrees[0];
            var model = comp.GetSemanticModel(tree);
            var declarators = tree.GetRoot().DescendantNodes().OfType<VariableDeclaratorSyntax>().ToArray();

            var symbol = model.GetDeclaredSymbol(declarators[0]).GetSymbol<LocalSymbol>();
            Assert.Equal("System.String?", symbol.TypeWithAnnotations.ToTestDisplayString());
            Assert.Equal(NullableAnnotation.Annotated, symbol.TypeWithAnnotations.NullableAnnotation);

            symbol = model.GetDeclaredSymbol(declarators[1]).GetSymbol<LocalSymbol>();
            Assert.Equal("System.String?", symbol.TypeWithAnnotations.ToTestDisplayString());
            Assert.Equal(NullableAnnotation.Annotated, symbol.TypeWithAnnotations.NullableAnnotation);

            symbol = model.GetDeclaredSymbol(declarators[2]).GetSymbol<LocalSymbol>();
            Assert.Equal("System.String?", symbol.TypeWithAnnotations.ToTestDisplayString());
            Assert.Equal(NullableAnnotation.Annotated, symbol.TypeWithAnnotations.NullableAnnotation);
        }

