using System;

delegate void D1(string s);
delegate void D2(string? s);

class C
{
    void M(Action<string> a1, Action<string?> a2, D1 d1, D2 d2)
    {
        _ = new D1(a1);
        _ = new D1(a2);
        _ = new D2(a1); // 1
        _ = new D2(a1!);
        _ = new D2(a2);

        _ = new D1(d1);
        _ = new D1(d2);
        _ = new D2(d1); // 2
        _ = new D2(d1!);
        _ = new D2(d2);

        _ = new Action<string>(d1);
        _ = new Action<string>(d2);
        _ = new Action<string?>(d1); // 3
        _ = new Action<string?>(d1!);
        _ = new Action<string?>(d2);

        _ = new Action<string>(a1);
        _ = new Action<string>(a2);
        _ = new Action<string?>(a1); // 4
        _ = new Action<string?>(a1!);
        _ = new Action<string?>(a2);
    }
}
";
