        [Fact]
        [WorkItem(44129, "https://github.com/dotnet/roslyn/issues/44129")]
        public void DelegateCreation_FromMethodGroup_NullabilityAttributes_02()
        {
            var source = @"
using System.Diagnostics.CodeAnalysis;

delegate void D1(out string s);
delegate bool D2(out string s);
delegate void D3(ref string s);

class C
{
    public void M1(out string s) => throw null!;
    public void M2(out string? s) => throw null!;
    public void M3([MaybeNull] out string s) => throw null!;
    public bool M4([MaybeNullWhen(false)] out string s) => throw null!;

    public void M5(ref string s) => throw null!;
    public void M6([MaybeNull] ref string s) => throw null!;

    static void M()
    {
