        [Fact, WorkItem(29635, "https://github.com/dotnet/roslyn/issues/29635")]
        public void Discard_02()
        {
            var source =
@"#nullable disable
class C<T>
{
#nullable enable
    void F(object? o1, object? o2, C<object> o3, C<object?> o4)
    {
        if (o1 is null) throw null!;
        _ /*T:object!*/ = o1;
        _ /*T:object?*/ = o2;
        _ /*T:C<object!>!*/ = o3;
        _ /*T:C<object?>!*/ = o4;
    }
#nullable disable
    void F(C<object> o)
    {
        _ /*T:C<object>!*/ = o;
    }
}";
            var comp = CreateCompilation(source, parseOptions: TestOptions.Regular.WithFeature(CodeAnalysis.Feature.RunNullableAnalysis, "always"), options: WithNullableEnable());
            comp.VerifyDiagnostics();
            comp.VerifyTypes();

            var tree = comp.SyntaxTrees.Single();
            var discards = tree.GetRoot().DescendantNodes().OfType<AssignmentExpressionSyntax>().Select(a => a.Left).ToArray();
            var model = comp.GetSemanticModel(tree, ignoreAccessibility: false);

            var discard1 = model.GetSymbolInfo(discards[0]).Symbol;
            Assert.Equal(SymbolKind.Discard, discard1.Kind);
            Assert.Equal("object _", discard1.ToDisplayString(SymbolDisplayFormat.MinimallyQualifiedFormat));

            var discard2 = model.GetSymbolInfo(discards[1]).Symbol;
            Assert.Equal(SymbolKind.Discard, discard2.Kind);
            Assert.Equal("object? _", discard2.ToDisplayString(SymbolDisplayFormat.MinimallyQualifiedFormat));

            var discard3 = model.GetSymbolInfo(discards[2]).Symbol;
            Assert.Equal(SymbolKind.Discard, discard3.Kind);
            Assert.Equal("C<object> _", discard3.ToDisplayString(SymbolDisplayFormat.MinimallyQualifiedFormat));

            var discard4 = model.GetSymbolInfo(discards[3]).Symbol;
            Assert.Equal(SymbolKind.Discard, discard4.Kind);
            Assert.Equal("C<object?> _", discard4.ToDisplayString(SymbolDisplayFormat.MinimallyQualifiedFormat));

            var discard5 = model.GetSymbolInfo(discards[4]).Symbol;
            Assert.Equal(SymbolKind.Discard, discard5.Kind);
            Assert.Equal("C<object> _", discard5.ToDisplayString(SymbolDisplayFormat.MinimallyQualifiedFormat));
        }

