        [Fact, WorkItem(36503, "https://github.com/dotnet/roslyn/issues/36503")]
        public void Discard_OutDiscard()
        {
            var source = @"
class C
{
    void M<T>(out T t) => throw null!;
    void M2()
    {
        M<string?>(out var _);
        M<object?>(out _);
        M<string>(out var _);
#nullable disable annotations
        M<object>(out _);
    }
}";
            var comp = CreateNullableCompilation(source);
            comp.VerifyDiagnostics();
            var tree = comp.SyntaxTrees.Single();
            var model = comp.GetSemanticModel(tree);
            var arguments = tree.GetRoot().DescendantNodes().OfType<ArgumentSyntax>();

            var discard1 = arguments.First().Expression;
            Assert.Equal("var _", discard1.ToString());
            Assert.Equal("System.String?", model.GetTypeInfoAndVerifyIOperation(discard1).Type.ToTestDisplayString());
            Assert.Equal(CodeAnalysis.NullableAnnotation.Annotated, model.GetTypeInfo(discard1).Nullability.Annotation);

            var discard2 = arguments.Skip(1).First().Expression;
            Assert.Equal("_", discard2.ToString());
            Assert.Equal("System.Object?", model.GetTypeInfoAndVerifyIOperation(discard2).Type.ToTestDisplayString());
            Assert.Equal(CodeAnalysis.NullableAnnotation.Annotated, model.GetTypeInfo(discard2).Nullability.Annotation);

            var discard3 = arguments.Skip(2).First().Expression;
            Assert.Equal("var _", discard3.ToString());
            Assert.Equal("System.String", model.GetTypeInfoAndVerifyIOperation(discard3).Type.ToTestDisplayString());
            Assert.Equal(CodeAnalysis.NullableAnnotation.NotAnnotated, model.GetTypeInfo(discard3).Nullability.Annotation);

            var discard4 = arguments.Skip(3).First().Expression;
            Assert.Equal("_", discard4.ToString());
            Assert.Equal("System.Object", model.GetTypeInfoAndVerifyIOperation(discard4).Type.ToTestDisplayString());
            Assert.Equal(CodeAnalysis.NullableAnnotation.NotAnnotated, model.GetTypeInfo(discard4).Nullability.Annotation);
        }

        [Fact, WorkItem(36503, "https://github.com/dotnet/roslyn/issues/35010")]
        public void Discard_Deconstruction()
        {
            var source = @"
class C
{
    void M(string x, object y)
    {
        x = null; // 1
        y = null; // 2
        (var _, _) = (x, y);
    }
}";
            var comp = CreateNullableCompilation(source);
            comp.VerifyDiagnostics(
                // (6,13): warning CS8600: Converting null literal or possible null value to non-nullable type.
                //         x = null; // 1
                Diagnostic(ErrorCode.WRN_ConvertingNullableToNonNullable, "null").WithLocation(6, 13),
                // (7,13): warning CS8600: Converting null literal or possible null value to non-nullable type.
                //         y = null; // 2
                Diagnostic(ErrorCode.WRN_ConvertingNullableToNonNullable, "null").WithLocation(7, 13)
                );
            var tree = comp.SyntaxTrees.Single();
            var model = comp.GetSemanticModel(tree);
            var arguments = tree.GetRoot().DescendantNodes().OfType<ArgumentSyntax>();

            // https://github.com/dotnet/roslyn/issues/35010: handle GetTypeInfo for deconstruction variables, discards, foreach deconstructions and nested deconstructions
            var discard1 = (DeclarationExpressionSyntax)arguments.First().Expression;
            Assert.Equal("var _", discard1.ToString());
            Assert.Equal(CodeAnalysis.NullableAnnotation.None, model.GetTypeInfoAndVerifyIOperation(discard1.Designation).Nullability.Annotation);
            Assert.Equal("System.String", model.GetTypeInfo(discard1).Type.ToTestDisplayString());
            Assert.Equal(CodeAnalysis.NullableAnnotation.None, model.GetTypeInfo(discard1).Nullability.Annotation);
            Assert.Null(model.GetSymbolInfo(discard1).Symbol);
            Assert.Null(model.GetSymbolInfo(discard1.Designation).Symbol);
            Assert.Null(model.GetDeclaredSymbol(discard1));
            Assert.Null(model.GetDeclaredSymbol(discard1.Designation));

            var discard2 = arguments.Skip(1).First().Expression;
            Assert.Equal("_", discard2.ToString());
            Assert.Equal("System.Object", model.GetTypeInfoAndVerifyIOperation(discard2).Type.ToTestDisplayString());
            Assert.Equal(CodeAnalysis.NullableAnnotation.None, model.GetTypeInfo(discard2).Nullability.Annotation);
            Assert.Equal("object _", model.GetSymbolInfo(discard2).Symbol.ToDisplayString(SymbolDisplayFormat.MinimallyQualifiedFormat));
            Assert.Null(model.GetDeclaredSymbol(discard2));
        }

        [Fact, WorkItem(35032, "https://github.com/dotnet/roslyn/issues/35032")]
        public void Discard_Pattern()
        {
            var source = @"
public class C
{
    public object? Property { get; }
    public void Deconstruct(out object? x, out object y) => throw null!;
    void M(C c)
    {
        _ = c is C { Property: _ };
        _ = c is C (_, _);
    }
}";
            var comp = CreateNullableCompilation(source);
            comp.VerifyDiagnostics();
            var tree = comp.SyntaxTrees.Single();
            var model = comp.GetSemanticModel(tree);
            var discardPatterns = tree.GetRoot().DescendantNodes().OfType<DiscardPatternSyntax>().ToArray();

            var discardPattern1 = discardPatterns[0];
            Assert.Equal("_", discardPattern1.ToString());
            Assert.Equal("System.Object", model.GetTypeInfo(discardPattern1).Type.ToTestDisplayString());
            // Nullability in patterns are not yet supported: https://github.com/dotnet/roslyn/issues/35032
            Assert.Equal(CodeAnalysis.NullableAnnotation.None, model.GetTypeInfo(discardPattern1).Nullability.Annotation);
            Assert.Null(model.GetSymbolInfo(discardPattern1).Symbol);

            var discardPattern2 = discardPatterns[1];
            Assert.Equal("_", discardPattern2.ToString());
            Assert.Equal("System.Object", model.GetTypeInfo(discardPattern2).Type.ToTestDisplayString());
            Assert.Equal(CodeAnalysis.NullableAnnotation.None, model.GetTypeInfo(discardPattern2).Nullability.Annotation);
            Assert.Null(model.GetSymbolInfo(discardPattern2).Symbol);
        }

