        public void Conversions_EnumToUnderlyingType_SemanticModel()
        {
            var source = @"
enum E
{
    A = 1,
    B = (int)A
}";
            var comp = CreateCompilation(new[] { source }, options: WithNullableEnable());
            var tree = comp.SyntaxTrees.Single();
