        [Fact]
        public void CompoundAssignment_SubSlots_01()
        {
            var source = """
                #nullable enable

                public class C
                {
                    public string? f1;
                    public string? f2;
                    public string? f3;

                    public static C operator +(C left, C right) => new();

                    public static void Main()
                    {
                        C c1 = new() { f1 = "a", f2 = "b" };
                        C c2 = new() { f1 = "a", f3 = "c" };
                        c1 += c2;

                        c1.f1.ToString(); // 1
                        c1.f2.ToString(); // 2
                        c1.f3.ToString(); // 3
                    }
                }
