#nullable enable
public class C
{
    public static string field;
}
public class D
{
#nullable enable
    public static string field;

#nullable enable
    public static string Method(string s) => throw null;

#nullable enable
    public static string Property { get; set; }

#nullable enable
    public static event System.Action Event;
#nullable disable
    void M()
    {
        C.field = null;
        D.field = null;
        D.Method(null);
        D.Property = null;
        D.Event();
    }
}
";
