        [WorkItem(40818, "https://github.com/dotnet/roslyn/issues/40818")]
        [Fact]
        public void ParameterDefaultValue_05()
        {
            var source = @"
class C
{
    T M1<T>(T t = default) // 1
        => t;

    T M2<T>(T t = default) where T : class? // 2
        => t;

    T M3<T>(T t = default) where T : class // 3
        => t;

    T M4<T>(T t = default) where T : notnull // 4
        => t;

    T M5<T>(T? t = default) where T : struct
        => t.Value; // 5

    T M6<T>(T? t = default(T)) where T : struct // 6
        => t.Value; // 7
}";
            var comp = CreateCompilation(new[] { source }, options: WithNullableEnable(), parseOptions: TestOptions.Regular8);
            var expected = new[]
            {
                // (4,19): warning CS8601: Possible null reference assignment.
                //     T M1<T>(T t = default) // 1
                Diagnostic(ErrorCode.WRN_NullReferenceAssignment, "default").WithLocation(4, 19),
                // (7,19): warning CS8625: Cannot convert null literal to non-nullable reference type.
                //     T M2<T>(T t = default) where T : class? // 2
                Diagnostic(ErrorCode.WRN_NullAsNonNullable, "default").WithLocation(7, 19),
                // (10,19): warning CS8625: Cannot convert null literal to non-nullable reference type.
                //     T M3<T>(T t = default) where T : class // 3
                Diagnostic(ErrorCode.WRN_NullAsNonNullable, "default").WithLocation(10, 19),
                // (13,19): warning CS8601: Possible null reference assignment.
                //     T M4<T>(T t = default) where T : notnull // 4
                Diagnostic(ErrorCode.WRN_NullReferenceAssignment, "default").WithLocation(13, 19),
                // (17,12): warning CS8629: Nullable value type may be null.
                //         => t.Value; // 5
                Diagnostic(ErrorCode.WRN_NullableValueTypeMayBeNull, "t").WithLocation(17, 12),
                // (19,16): error CS1770: A value of type 'T' cannot be used as default parameter for nullable parameter 't' because 'T' is not a simple type
                //     T M6<T>(T? t = default(T)) where T : struct // 6
                Diagnostic(ErrorCode.ERR_NoConversionForNubDefaultParam, "t").WithArguments("T", "t").WithLocation(19, 16),
                // (20,12): warning CS8629: Nullable value type may be null.
                //         => t.Value; // 7
                Diagnostic(ErrorCode.WRN_NullableValueTypeMayBeNull, "t").WithLocation(20, 12)
            };

            comp.VerifyDiagnostics(expected);

            comp = CreateCompilation(new[] { source }, options: WithNullableEnable());
            comp.VerifyDiagnostics(expected);
        }

