        [Fact, WorkItem(43399, "https://github.com/dotnet/roslyn/issues/43399")]
        public void ParameterDefaultValue_09()
        {
            var source = @"
using System.Runtime.InteropServices;

public class C {
    public void M1([Optional, DefaultParameterValue(null!)] object obj)
    {
        obj.ToString();
    }
    public void M2([Optional, DefaultParameterValue(default)] object obj)
    {
        obj.ToString();
    }
    public void M3([Optional, DefaultParameterValue(null)] object obj = null)
    {
        obj.ToString();
    }
}
";
            // 'M1' doesn't seem like a scenario where an error or warning should be given.
            // However, we can't round trip the concept that the parameter default value was suppressed.
            // Therefore even if we fixed this, this usage could result in strange corner case behaviors when
            // emitting the method to metadata and calling it in source.
            var comp = CreateCompilation(source, options: WithNullableEnable());
            comp.VerifyDiagnostics(
                // (5,31): error CS8017: The parameter has multiple distinct default values.
                //     public void M1([Optional, DefaultParameterValue(null!)] object obj)
                Diagnostic(ErrorCode.ERR_ParamDefaultValueDiffersFromAttribute, "DefaultParameterValue(null!)").WithLocation(5, 31),
                // (9,31): error CS8017: The parameter has multiple distinct default values.
                //     public void M2([Optional, DefaultParameterValue(default)] object obj)
                Diagnostic(ErrorCode.ERR_ParamDefaultValueDiffersFromAttribute, "DefaultParameterValue(default)").WithLocation(9, 31),
                // (13,21): error CS1745: Cannot specify default parameter value in conjunction with DefaultParameterAttribute or OptionalAttribute
                //     public void M3([Optional, DefaultParameterValue(null)] object obj = null)
