        {
            // In some frameworks, System.String doesn't implement IEnumerable, but for compat reasons the compiler
            // will still allow foreach'ing over these strings.

            var systemSource = @"
namespace System
{
    public class Object { }
    public struct Void { }
    public class ValueType { }
    public abstract class Enum : ValueType { }
    public struct Boolean { }
    public struct Int32 { }
    public struct Byte { }
    public class Exception { }
    public struct Char
    {
        public string ToString() => throw null!;
    }

    public class String
    {
        public int Length { get; }

        [System.Runtime.CompilerServices.IndexerName(""Chars"")]
        public char this[int i] => throw null!;
    }

    public interface IDisposable
    {
        void Dispose();
    }

    public abstract class Attribute
    {
        protected Attribute() { }
    }

    public enum AttributeTargets
    {
        Assembly = 0x0001,
        Module = 0x0002,
        Class = 0x0004,
        Struct = 0x0008,
        Enum = 0x0010,
        Constructor = 0x0020,
        Method = 0x0040,
        Property = 0x0080,
        Field = 0x0100,
        Event = 0x0200,
        Interface = 0x0400,
        Parameter = 0x0800,
        Delegate = 0x1000,
        ReturnValue = 0x2000,
        GenericParameter = 0x4000,
        All = 0x7FFF
    }

    public sealed class AttributeUsageAttribute : Attribute
    {
        public AttributeUsageAttribute(AttributeTargets validOn) { }
        public bool AllowMultiple { get; set; }
        public bool Inherited { get; set; }
    }
}

namespace System.Runtime.CompilerServices
{
    using System;

    public sealed class IndexerNameAttribute: Attribute
    {
        public IndexerNameAttribute(String indexerName)
        {}
    }
}

namespace System.Reflection {

    using System;

    public sealed class DefaultMemberAttribute : Attribute
    {
        public DefaultMemberAttribute(String memberName)
        {}
    }
}

namespace System.Collections
{
    public interface IEnumerable
    {
        IEnumerator GetEnumerator();
    }

    public interface IEnumerator
    {
        object Current { get; }
        bool MoveNext();
    }
}";

            var source = @"
