        [WorkItem(27961, "https://github.com/dotnet/roslyn/issues/27961")]
        [Fact]
        public void TypeInference_LowerBounds_TopLevelNullability_01()
        {
            var source0 =
@"public class A
{
    public static A F;
}";
            var comp0 = CreateCompilation(source0, parseOptions: TestOptions.Regular7);
            comp0.VerifyDiagnostics();
            var ref0 = comp0.EmitToImageReference();

            var source =
@"class C
{
    static T F<T>(T x, T y) => throw null!;
    static void G(A? x, A y)
    {
        var z = A.F;
        F(x, x)/*T:A?*/;
        F(x, y)/*T:A?*/;
        F(x, z)/*T:A?*/;
        F(y, x)/*T:A?*/;
        F(y, y)/*T:A!*/;
        F(y, z)/*T:A!*/;
        F(z, x)/*T:A?*/;
        F(z, y)/*T:A!*/;
        F(z, z)/*T:A!*/;
    }
}";
            var comp = CreateCompilation(new[] { source }, options: WithNullableEnable(), references: new[] { ref0 });
            comp.VerifyTypes();
            comp.VerifyDiagnostics();
        }

