        [Fact]
        public void TypeInference_12()
        {
            var source =
@"class C<T>
{
    internal T F;
}
class C
{
    static C<T> Create<T>(T t)
    {
        return new C<T>();
    }
    static void F(object? x)
    {
        if (x == null)
        {
            Create(x).F = null;
            var y = Create(x);
            y.F = null;
        }
        else
        {
            Create(x).F = null; // warn
            var y = Create(x);
            y.F = null; // warn
        }
    }
}";
            var comp = CreateCompilation(new[] { source }, options: WithNullableEnable());
            comp.VerifyDiagnostics(
                // (3,16): warning CS8618: Non-nullable field 'F' is uninitialized. Consider declaring the field as nullable.
                //     internal T F;
                Diagnostic(ErrorCode.WRN_UninitializedNonNullableField, "F").WithArguments("field", "F").WithLocation(3, 16),
                // (21,27): warning CS8625: Cannot convert null literal to non-nullable reference type.
                //             Create(x).F = null; // warn
                Diagnostic(ErrorCode.WRN_NullAsNonNullable, "null").WithLocation(21, 27),
                // (23,19): warning CS8625: Cannot convert null literal to non-nullable reference type.
                //             y.F = null; // warn
                Diagnostic(ErrorCode.WRN_NullAsNonNullable, "null").WithLocation(23, 19));
        }

        [Fact]
        [WorkItem(49472, "https://github.com/dotnet/roslyn/issues/49472")]
        public void TypeInference_13()
        {
            var source =
@"#nullable enable
using System;
using System.Collections.Generic;
static class Program
{
    static void Main()
    {
        var d1 = new Dictionary<string, string?>();
        var d2 = d1.ToDictionary(kv => kv.Key, kv => kv.Value);
        d2[""""].ToString();
    }
    static Dictionary<TKey, TValue> ToDictionary<TSource, TKey, TValue>(this IEnumerable<TSource> e, Func<TSource, TKey> k, Func<TSource, TValue> v)
    {
        return new Dictionary<TKey, TValue>();
    }
}";
            var comp = CreateCompilation(source);
            comp.VerifyDiagnostics(
                // (10,9): warning CS8602: Dereference of a possibly null reference.
                //         d2[""].ToString();
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, @"d2[""""]").WithLocation(10, 9));

            var syntaxTree = comp.SyntaxTrees[0];
            var model = comp.GetSemanticModel(syntaxTree);
            var localDeclaration = syntaxTree.GetRoot().DescendantNodes().OfType<VariableDeclaratorSyntax>().ElementAt(1);
            var symbol = model.GetDeclaredSymbol(localDeclaration);
            Assert.Equal("System.Collections.Generic.Dictionary<System.String!, System.String?>? d2", symbol.ToTestDisplayString(includeNonNullable: true));
        }

