@"interface I<T>
{
    T P { get; set; }
}
class A { }
class B
{
    static void F1<T>(T t1) where T : A
    {
        t1.ToString();
        t1 = default; // 1
    }
    static void F2<T>(T t2) where T : A?
    {
        t2.ToString(); // 2
        t2 = default;
    }
    static void F3<T>(T t3) where T : I<T>
    {
        t3.P.ToString();
        t3 = default;
    }
    static void F4<T>(T t4) where T : I<T>?
    {
        t4.P.ToString(); // 3 and 4
        t4.P = default; // 5
        t4 = default;
    }
    static void F5<T>(T t5) where T : I<T?>
    {
        t5.P.ToString(); // 6 and 7
        t5.P = default;
        t5 = default;
    }
}";
            var comp = CreateCompilation(new[] { source }, options: WithNullableEnable(), parseOptions: TestOptions.Regular8);
            comp.VerifyDiagnostics(
                // (11,14): warning CS8600: Converting null literal or possible null value to non-nullable type.
                //         t1 = default; // 1
                Diagnostic(ErrorCode.WRN_ConvertingNullableToNonNullable, "default").WithLocation(11, 14),
                // (15,9): warning CS8602: Dereference of a possibly null reference.
                //         t2.ToString(); // 2
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "t2").WithLocation(15, 9),
                // (25,9): warning CS8602: Dereference of a possibly null reference.
                //         t4.P.ToString(); // 3 and 4
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "t4").WithLocation(25, 9),
                // (25,9): warning CS8602: Dereference of a possibly null reference.
                //         t4.P.ToString(); // 3 and 4
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "t4.P").WithLocation(25, 9),
                // (26,16): warning CS8601: Possible null reference assignment.
                //         t4.P = default; // 5
                Diagnostic(ErrorCode.WRN_NullReferenceAssignment, "default").WithLocation(26, 16),
                // (29,41): error CS8627: A nullable type parameter must be known to be a value type or non-nullable reference type unless language version '9.0' or greater is used. Consider changing the language version or adding a 'class', 'struct', or type constraint.
                //     static void F5<T>(T t5) where T : I<T?>
                Diagnostic(ErrorCode.ERR_NullableUnconstrainedTypeParameter, "T?").WithArguments("9.0").WithLocation(29, 41),
                // (31,9): warning CS8602: Dereference of a possibly null reference.
                //         t5.P.ToString(); // 6 and 7
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "t5.P").WithLocation(31, 9)
                );
        }

        [Fact]
        public void Constraints_02()
        {
            var source =
@"
class B
{
    public static void F1<T1>(T1? t1) where T1 : class
    {
    }

    public static void F2<T2>(T2 t2) where T2 : class?
    {
    }
}";
            var comp = CreateCompilation(new[] { source }, options: WithNullableEnable());
            comp.VerifyDiagnostics(
            );

            CompileAndVerify(comp, sourceSymbolValidator: symbolValidator, symbolValidator: symbolValidator);
            void symbolValidator(ModuleSymbol m)
            {
                bool isSource = !(m is PEModuleSymbol);

                var b = m.GlobalNamespace.GetMember("B");
                if (isSource)
                {
                    Assert.Empty(b.GetAttributes());
                }
                else
                {
                    Assert.Equal("System.Runtime.CompilerServices.NullableContextAttribute(1)", b.GetAttributes().First().ToString());
                }
                var f1 = (MethodSymbol)m.GlobalNamespace.GetMember("B.F1");
                Assert.Equal("void B.F1<T1>(T1? t1) where T1 : class!", f1.ToDisplayString(SymbolDisplayFormat.TestFormatWithConstraints));
                TypeParameterSymbol t1 = f1.TypeParameters[0];
                Assert.False(t1.ReferenceTypeConstraintIsNullable);
                Assert.Empty(t1.GetAttributes());

                var f2 = (MethodSymbol)m.GlobalNamespace.GetMember("B.F2");
                Assert.Equal("void B.F2<T2>(T2 t2) where T2 : class?", f2.ToDisplayString(SymbolDisplayFormat.TestFormat.WithGenericsOptions(SymbolDisplayFormat.TestFormat.GenericsOptions | SymbolDisplayGenericsOptions.IncludeTypeConstraints)));
                Assert.Equal("void B.F2<T2>(T2 t2) where T2 : class", f2.ToDisplayString(SymbolDisplayFormat.TestFormat.WithGenericsOptions(SymbolDisplayFormat.TestFormat.GenericsOptions | SymbolDisplayGenericsOptions.IncludeTypeConstraints).
                    WithMiscellaneousOptions(SymbolDisplayFormat.TestFormatWithConstraints.MiscellaneousOptions &
                        ~(SymbolDisplayMiscellaneousOptions.IncludeNullableReferenceTypeModifier | SymbolDisplayMiscellaneousOptions.IncludeNotNullableReferenceTypeModifier))));

                TypeParameterSymbol t2 = f2.TypeParameters[0];
                Assert.True(t2.ReferenceTypeConstraintIsNullable);
                if (isSource)
                {
                    Assert.Empty(t2.GetAttributes());
                }
                else
                {
                    Assert.Equal("System.Runtime.CompilerServices.NullableAttribute(2)", t2.GetAttributes().Single().ToString());
                }
            }
        }

