        [Fact]
        public void UnconstrainedTypeParameter_Local()
        {
            var source =
@"
#pragma warning disable CS0168
class B
{
    public static void F1<T1>()
    {
        T1? x;
    }
}";
            var comp = CreateCompilation(new[] { source }, options: WithNullableEnable(), parseOptions: TestOptions.Regular8);

            comp.VerifyDiagnostics(
                // (7,9): error CS8627: A nullable type parameter must be known to be a value type or non-nullable reference type unless language version '9.0' or greater is used. Consider changing the language version or adding a 'class', 'struct', or type constraint.
                //         T1? x;
                Diagnostic(ErrorCode.ERR_NullableUnconstrainedTypeParameter, "T1?").WithArguments("9.0").WithLocation(7, 9)
            );
        }

        [Fact]
        public void ConstraintsChecks_01()
        {
            var source =
@"
