        M1(a2); // 5
        M1(b2); 
        M1(c2); // 6
        M1<ID<string?>>(a2); // 7
        M1<ID<string?>>(b2); // 8
        M1<ID<string>?>(b2); // 9
        M1<ID<string>>(b2);
    }
}
";
