    static void FOut()
    {
        FOut0<SOut0>();
        FOut0<SOut1>();
        FOut0<SOut2>();
        FOut1<SOut0>();
        FOut1<SOut1>();
        FOut1<SOut2>();
        FOut2<SOut0>();
