        [Fact]
        [WorkItem(35083, "https://github.com/dotnet/roslyn/issues/35083")]
        public void GenericSubstitution_07()
        {
            var source =
@"
class A
{
    void M1<T>()
    {
    }
}
";
            var comp = CreateCompilation(new[] { source });
            comp.VerifyDiagnostics();

            var a = comp.GetTypeByMetadataName("A");
            var m1 = a.GetMember<MethodSymbol>("M1");

            var m11 = new[]
                {
                    m1.Construct(ImmutableArray.Create(TypeWithAnnotations.Create(a, NullableAnnotation.Annotated))),
                    m1.Construct(ImmutableArray.Create(TypeWithAnnotations.Create(a, NullableAnnotation.NotAnnotated))),
                    m1.Construct(ImmutableArray.Create(TypeWithAnnotations.Create(a, NullableAnnotation.Oblivious)))
                };

            var m12 = new[]
                {
                    m1.Construct(ImmutableArray.Create(TypeWithAnnotations.Create(a, NullableAnnotation.Annotated))),
                    m1.Construct(ImmutableArray.Create(TypeWithAnnotations.Create(a, NullableAnnotation.NotAnnotated))),
                    m1.Construct(ImmutableArray.Create(TypeWithAnnotations.Create(a, NullableAnnotation.Oblivious)))
                };

            for (int i = 0; i < m11.Length; i++)
            {
                var method1 = m11[i];

                Assert.True(method1.Equals(method1));

                for (int j = 0; j < m12.Length; j++)
                {
                    var method2 = m12[j];

                    // always equal by default
                    Assert.True(method1.Equals(method2));
                    Assert.True(method2.Equals(method1));

                    // can differ when considering nullability
                    if (i == j)
                    {
                        Assert.True(method1.Equals(method2, SymbolEqualityComparer.IncludeNullability.CompareKind));
                        Assert.True(method2.Equals(method1, SymbolEqualityComparer.IncludeNullability.CompareKind));
                    }
                    else
                    {
                        Assert.False(method1.Equals(method2, SymbolEqualityComparer.IncludeNullability.CompareKind));
                        Assert.False(method2.Equals(method1, SymbolEqualityComparer.IncludeNullability.CompareKind));
                    }

                    Assert.Equal(method1.GetHashCode(), method2.GetHashCode());
                }
            }
        }

        [Fact]
        [WorkItem(30171, "https://github.com/dotnet/roslyn/issues/30171")]
        public void NonNullTypesContext_01()
        {
            var source =
@"
using System.Diagnostics.CodeAnalysis;

class A
{
#nullable disable PLACEHOLDER
    B[] F1;

#nullable enable PLACEHOLDER
    C[] F2;
}

class B {}
class C {}
";
            var comp1 = CreateCompilation(new[] { source.Replace("PLACEHOLDER", "") });
            verify(comp1);

            var comp2 = CreateCompilation(new[] { source.Replace("PLACEHOLDER", "annotations") });
            verify(comp2);

            void verify(CSharpCompilation comp)
            {
                var f1 = comp.GetMember<FieldSymbol>("A.F1");
                Assert.Equal("B[]", f1.TypeWithAnnotations.ToTestDisplayString(includeNonNullable: true));

                var f2 = comp.GetMember<FieldSymbol>("A.F2");
                Assert.Equal("C![]!", f2.TypeWithAnnotations.ToTestDisplayString(includeNonNullable: true));

                var tree = comp.SyntaxTrees.First();
                var model = comp.GetSemanticModel(tree);
                var arrays = tree.GetRoot().DescendantNodes().OfType<ArrayTypeSyntax>().ToArray();

                Assert.Equal(2, arrays.Length);

                Assert.Equal("B[]", model.GetTypeInfo(arrays[0]).Type.ToTestDisplayString(includeNonNullable: true));
                Assert.Equal("C![]", model.GetTypeInfo(arrays[1]).Type.ToTestDisplayString(includeNonNullable: true));
            }
        }

