        [WorkItem(31858, "https://github.com/dotnet/roslyn/issues/31858")]
        public void ExplicitInterfaceImplementation_08()
        {
            var source1 = @"
public interface I1<I1T1>
{
    void M();
}

public interface I2<I2T1, I2T2> : I1<(I2T1, I2T2)>
{
