        [Fact, WorkItem(718176, "https://devdiv.visualstudio.com/DefaultCollection/DevDiv/_workitems/edit/718176")]
        public void AccessPropertyWithoutArguments()
        {
            var source1 =
@"Imports System
Imports System.Runtime.InteropServices
<Assembly: PrimaryInteropAssembly(0, 0)> 
