    }
}";
            var comp = CreateCompilation(source2, new[] { ref1.WithEmbedInteropTypes(true), CSharpRef }, options: WithNullableEnable(TestOptions.ReleaseExe));
            CompileAndVerify(comp, expectedOutput: "4");
        }

