        y = (T)x;
        y.ToString();
    }
    void M2<T>(dynamic? x)
    {
        if (x != null) return;
        T y;
        y = x;
        y = (T)x;
        y.ToString(); // 1
    }
    void M3<T>(dynamic? x)
    {
        if (x != null)
        {
            T y;
            y = x;
            y = (T)x;
            y.ToString();
        }
        else
        {
            T y;
            y = x;
            y = (T)x;
            y.ToString(); // 2
        }
    }
    void M4<T>(dynamic? x)
    {
        if (x == null)
        {
            T y;
            y = x;
            y = (T)x;
            y.ToString(); // 3
        }
        else
        {
            T y;
            y = x;
            y = (T)x;
            y.ToString();
        }
    }
    void M5<T>(dynamic? x)
    {
        // Since `||` here could be a user-defined `operator |` invocation,
        // no reasonable inferences can be made.
        if (x == null || false)
        {
            T y;
            y = x;
            y = (T)x;
            y.ToString(); // 4
        }
        else
        {
            T y;
            y = x;
            y = (T)x;
            y.ToString(); // 5
        }
    }
    void M6<T>(dynamic? x)
    {
        // Since `&&` here could be a user-defined `operator &` invocation,
        // no reasonable inferences can be made.
        if (x == null && true)
        {
            T y;
            y = x;
            y = (T)x;
            y.ToString(); // 6
        }
        else
        {
            T y;
            y = x;
            y = (T)x;
            y.ToString(); // 7
        }
    }
    void M7<T>(dynamic? x)
    {
        if (!(x == null))
        {
            T y;
            y = x;
            y = (T)x;
            y.ToString();
        }
        else
        {
            T y;
            y = x;
            y = (T)x;
            y.ToString(); // 8
        }
    }
    void M8<T>(dynamic? x)
    {
        if (!(x != null))
        {
            T y;
            y = x;
            y = (T)x;
            y.ToString(); // 9
        }
        else
        {
            T y;
            y = x;
            y = (T)x;
            y.ToString();
        }
    }
}
