        [Fact]
        [WorkItem(33295, "https://github.com/dotnet/roslyn/issues/33295")]
        public void NullabilityOfTypeParameters_263()
        {
            var source = @"
#nullable enable
class C<T>
{
  public T FieldWithInferredAnnotation;
}
class C
{
  static void Main()
  {
    Test(null);
  }

  static void Test(string? s)
  {
    s = """";
    hello:
    var c = GetC(s);
    c.FieldWithInferredAnnotation.ToString();
    s = null;
    goto hello;
  }

  public static C<T> GetC<T>(T t) => new C<T> { FieldWithInferredAnnotation = t };
  public static T GetT<T>(T t) => t;
}";

            CreateCompilation(source, options: WithNullableEnable()).VerifyDiagnostics(
                // (5,12): warning CS8618: Non-nullable field 'FieldWithInferredAnnotation' must contain a non-null value when exiting constructor. Consider adding the 'required' modifier or declaring the field as nullable.
                //   public T FieldWithInferredAnnotation;
                Diagnostic(ErrorCode.WRN_UninitializedNonNullableField, "FieldWithInferredAnnotation").WithArguments("field", "FieldWithInferredAnnotation").WithLocation(5, 12),
                // (19,5): warning CS8602: Dereference of a possibly null reference.
                //     c.FieldWithInferredAnnotation.ToString();
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "c.FieldWithInferredAnnotation").WithLocation(19, 5));
        }

        [Fact]
        public void UpdateFieldFromReceiverType()
        {
            var source =
@"class A<T> { }
class B<T>
{
    internal T F = default!;
}
class Program
{
    internal static B<T> Create<T>(T t) => throw null!;
    static void M1(object x, object? y)
    {
        var b1 = Create(x);
        b1.F = x;
        b1.F = y; // 1
    }
    static void M2(A<object?> x, A<object> y, A<object?> z)
    {
        var b2 = Create(x);
        b2.F = y; // 2
        b2.F = z;
    }
}";
            var comp = CreateCompilation(new[] { source }, options: WithNullableEnable());
            comp.VerifyDiagnostics(
