        [Fact]
        public void NullableT_As_ValueTypeConstraint_01()
        {
            var source =
@"abstract class A<T>
{
    internal abstract void F<U>(U u) where U : T;
}
class B1 : A<int>
{
    internal override void F<U>(U u)
    {
        _ = (u as U?).Value;
        _ = (u as int?).Value; // 1
    }
}
class B2 : A<int?>
{
    internal override void F<U>(U u)
    {
        _ = (u as int?).Value; // 2
    }
}";
            // Implicit conversions are not allowed from U to int in B1.F or from U to int? in B2.F,
            // so those conversions are not handled in NullableWalker either.
            var comp = CreateCompilation(source, options: WithNullableEnable());
            comp.VerifyDiagnostics(
                // (10,14): warning CS8629: Nullable value type may be null.
                //         _ = (u as int?).Value; // 1
                Diagnostic(ErrorCode.WRN_NullableValueTypeMayBeNull, "u as int?").WithLocation(10, 14),
                // (17,14): warning CS8629: Nullable value type may be null.
                //         _ = (u as int?).Value; // 2
                Diagnostic(ErrorCode.WRN_NullableValueTypeMayBeNull, "u as int?").WithLocation(17, 14)
                );
        }

        [Fact]
        public void NullableT_As_ValueTypeConstraint_02()
        {
            var source =
@"abstract class A<T>
{
    internal abstract void F<U>(T t) where U : T;
}
class B1 : A<int>
{
