        public void LambdaReturnType_DifferentTupleNullability_01()
        {
            // See https://github.com/dotnet/roslyn/issues/32006
            // need to relax assertion in GetImplicitTupleLiteralConversion

            var source =
@"using System;
class Program
{
    static T F<T>(Func<bool, T> f)
    {
        return f(true);
    }
    static void G<T, U>()
        where T : class, new()
        where U : struct
    {
        F(b =>
            {
                if (b)
                {
                    T? t1 = null;
                    U? u2 = new U();
                    return (t1, u2);
                }
                return (null, null);
            })/*T:(T? t1, U? u2)*/;
        F(b =>
            {
                if (b) return (null, null);
                T? t2 = new T();
