@"using System;

class C
{
    static void Main()
    {
        Console.WriteLine(Test(42));
    }

    public static Test(object? a)
    {
        if (a == null) return;
        var x = (f1: a, f2: a);
        Func<object> f = () => x.Test(a);
        f();
    }
}

namespace System
{
    public struct ValueTuple<T1, T2>
    {
        public T1 Item1;
        public T2 Item2;

        public ValueTuple(T1 item1, T2 item2)
        {
            this.Item1 = item1;
            this.Item2 = item2;
        }

