        [Fact, WorkItem(33905, "https://github.com/dotnet/roslyn/issues/33905")]
        public void TestDiagnosticsInUnreachableCode()
        {
            var source =
@"#pragma warning disable 0162 // suppress unreachable statement warning
#pragma warning disable 0219 // suppress unused local warning
class G<T>
{
    public static void Test(bool b, object? o, G<string?> g)
    {
        if (b) M1(o); // 1
        M2(g); // 2
        if (false) M1(o);
        if (false) M2(g);
        if (false && M1(o)) M2(g);
        if (false && M2(g)) M1(o);
        if (true || M1(o))
            M2(g); // 3
        if (true || M2(g))
            M1(o); // 4
        G<string> g1 = g; // 5
        if (false) { G<string> g2 = g; }
        if (false) { object o1 = null; }
    }

    public static bool M1(object o) => true;
    public static bool M2(G<string> o) => true;
}";
            var comp = CreateCompilation(new[] { source }, options: WithNullableEnable());
            comp.VerifyDiagnostics(
                // (7,19): warning CS8604: Possible null reference argument for parameter 'o' in 'bool G<T>.M1(object o)'.
                //         if (b) M1(o); // 1
                Diagnostic(ErrorCode.WRN_NullReferenceArgument, "o").WithArguments("o", "bool G<T>.M1(object o)").WithLocation(7, 19),
                // (8,12): warning CS8620: Argument of type 'G<string?>' cannot be used for parameter 'o' of type 'G<string>' in 'bool G<T>.M2(G<string> o)' due to differences in the nullability of reference types.
                //         M2(g); // 2
                Diagnostic(ErrorCode.WRN_NullabilityMismatchInArgument, "g").WithArguments("G<string?>", "G<string>", "o", "bool G<T>.M2(G<string> o)").WithLocation(8, 12),
                // (14,16): warning CS8620: Argument of type 'G<string?>' cannot be used for parameter 'o' of type 'G<string>' in 'bool G<T>.M2(G<string> o)' due to differences in the nullability of reference types.
                //             M2(g); // 3
                Diagnostic(ErrorCode.WRN_NullabilityMismatchInArgument, "g").WithArguments("G<string?>", "G<string>", "o", "bool G<T>.M2(G<string> o)").WithLocation(14, 16),
                // (16,16): warning CS8604: Possible null reference argument for parameter 'o' in 'bool G<T>.M1(object o)'.
                //             M1(o); // 4
                Diagnostic(ErrorCode.WRN_NullReferenceArgument, "o").WithArguments("o", "bool G<T>.M1(object o)").WithLocation(16, 16),
                // (17,24): warning CS8619: Nullability of reference types in value of type 'G<string?>' doesn't match target type 'G<string>'.
                //         G<string> g1 = g; // 5
                Diagnostic(ErrorCode.WRN_NullabilityMismatchInAssignment, "g").WithArguments("G<string?>", "G<string>").WithLocation(17, 24));
        }

        [Fact]
        [WorkItem(33446, "https://github.com/dotnet/roslyn/issues/33446")]
        [WorkItem(34018, "https://github.com/dotnet/roslyn/issues/34018")]
        public void NullInferencesInFinallyClause()
        {
            var source =
@"class Node
{
    public Node? Next = null!;
    static void M1(Node node)
    {
        try
        {
            Mout(out node.Next);
        }
        finally
        {
            Mout(out node); // might set node to one in which node.Next == null
        }

        node.Next.ToString(); // 1
    }
    static void M2()
    {
        Node? node = null;
        try
        {
            Mout(out node);
        }
        finally
        {
            if (node is null) {} else {}
        }

        node.ToString();
    }
    static void M3()
    {
        Node? node = null;
        try
        {
            Mout(out node);
        }
        finally
        {
            node ??= node;
        }

        node.ToString();
    }
    static void M4()
    {
        Node? node = null;
        try
        {
            Mout(out node);
        }
        finally
        {
            try
            {
            }
            finally
            {
                if (node is null) {} else {}
            }
        }

        node.ToString();
    }
    static void M5()
    {
        Node? node = null;
        try
        {
            Mout(out node);
        }
        finally
        {
            try
            {
                if (node is null) {} else {}
            }
            finally
            {
            }
        }

        node.ToString();
    }
    static void M6()
    {
        Node? node = null;
        try
        {
            Mout(out node);
        }
        finally
        {
            (node, _) = (null, node);
        }

        node.ToString(); // 2
    }
    static void MN1()
    {
        Node? node = null;
        Mout(out node);
        if (node == null) {} else {}
        node.ToString(); // 3
    }
    static void MN2()
    {
        Node? node = null;
        try
        {
            Mout(out node);
        }
        finally
        {
            if (node == null) {} else {}
        }

        node.ToString();
    }
    static void Mout(out Node node) => node = null!;
}
";
            var comp = CreateCompilation(new[] { source }, options: WithNullableEnable());
            comp.VerifyDiagnostics(
                // (15,9): warning CS8602: Dereference of a possibly null reference.
                //         node.Next.ToString(); // 1
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "node.Next").WithLocation(15, 9),
                // (97,9): warning CS8602: Dereference of a possibly null reference.
                //         node.ToString(); // 2
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "node").WithLocation(97, 9),
                // (104,9): warning CS8602: Dereference of a possibly null reference.
                //         node.ToString(); // 3
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "node").WithLocation(104, 9));
        }

