        [Theory, CombinatorialData, WorkItem("https://github.com/dotnet/roslyn/issues/73338")]
        public void AnnotationMismatch_Interface_InstanceForwardingMethod(bool metadataOnly)
        {
            var source1 = """
                public class B
                {
                    public void M() { }
                }
                public interface I<T>
                {
                    void M();
                }
                """;
            var comp1 = CreateCompilation(source1, assemblyName: nameof(source1)).VerifyDiagnostics().EmitToImageReference();

            var source2 = """
                #nullable enable
                partial class C :
                    #nullable disable
                    I<C>
                    #nullable enable
                {
                }
                partial class C : B, I<C>
                {
                }
                """;
            var verifier = CompileAndVerify(source2, [comp1],
                emitOptions: CodeAnalysis.Emit.EmitOptions.Default.WithEmitMetadataOnly(metadataOnly),
                symbolValidator: validate);
            verifier.VerifyDiagnostics();

            static void validate(ModuleSymbol module)
            {
                var im = module.ReferencedAssemblySymbols.Single(a => a.Name == nameof(source1))
                    .GlobalNamespace.GetMember<MethodSymbol>("I.M");
                var cm = (MethodSymbol)Assert.Single(module.GlobalNamespace.GetTypeMember("C").GetMembers("I<C>.M"));
                var cme = Assert.Single(cm.GetExplicitInterfaceImplementations());
                Assert.Same(im, cme.OriginalDefinition);
            }
        }

        [Fact]
        public void PartialMethodsWithConstraints_01()
        {
            var source1 =
@"#nullable enable
using System;
partial class C
{
    static partial void F<T>() where T : IEquatable<T>;
}";
            var source2 =
@"using System;
partial class C
{
    static partial void F<T>() where T : IEquatable<T> { }
}";
            var comp = CreateCompilation(new[] { source1, source2 });
            comp.VerifyDiagnostics();

            var f = comp.GlobalNamespace.GetMember<MethodSymbol>("C.F");
            Assert.Equal("System.IEquatable<T>!", f.TypeParameters[0].ConstraintTypesNoUseSiteDiagnostics.Single().ToTestDisplayString(true));
            Assert.Equal("System.IEquatable<T>", f.PartialImplementationPart.TypeParameters[0].ConstraintTypesNoUseSiteDiagnostics.Single().ToTestDisplayString(true));
        }

        [Fact]
        public void PartialMethodsWithConstraints_02()
        {
            var source1 =
@"#nullable enable
using System;
partial class C
{
    static partial void F<T>() where T : class?, IEquatable<T?>;
}";
            var source2 =
@"using System;
partial class C
{
    static partial void F<T>() where T : class, IEquatable<T> { }
}";
            var comp = CreateCompilation(new[] { source1, source2 });
            comp.VerifyDiagnostics();

            var f = comp.GlobalNamespace.GetMember<MethodSymbol>("C.F");
            Assert.True(f.TypeParameters[0].ReferenceTypeConstraintIsNullable);
            Assert.Equal("System.IEquatable<T?>!", f.TypeParameters[0].ConstraintTypesNoUseSiteDiagnostics.Single().ToTestDisplayString(true));
            Assert.Null(f.PartialImplementationPart.TypeParameters[0].ReferenceTypeConstraintIsNullable);
            Assert.Equal("System.IEquatable<T>", f.PartialImplementationPart.TypeParameters[0].ConstraintTypesNoUseSiteDiagnostics.Single().ToTestDisplayString(true));
        }

