        public void PartialMethodsWithConstraints_03()
        {
            var source1 =
@"
partial class C
{
#nullable enable
    static partial void F<T>(I<T> x) where T : class;

#nullable disable
    static partial void F<T>(I<T> x) where T : class
#nullable enable
    {
        Test2(x);
    }

    void Test1<U>() where U : class?
    {
        F<U>(null);
    }

    static void Test2<S>(I<S?> x) where S : class { }
}

interface I<in S> { }
";
            var comp = CreateCompilation(new[] { source1 });
