                Diagnostic(ErrorCode.ERR_DuplicateExplicitImpl, "C2").WithArguments("I.Goo<T>(T?)").WithLocation(9, 7),
                // (9,12): error CS0535: 'C2' does not implement interface member 'I.Goo<T>(T?)'
                // class C2 : I
