        [Fact, WorkItem(29956, "https://github.com/dotnet/roslyn/issues/29956")]
        public void ConditionalExpression_InferredResultType()
        {
            CSharpCompilation c = CreateNullableCompilation(@"
class C
{
    void Test1(object? x)
    {
        M(x)?.Self()/*T:Box<object?>?*/;
        M(x)?.Value()/*T:object?*/;
        if (x == null) return;
        M(x)?.Self()/*T:Box<object!>?*/;
        M(x)?.Value()/*T:object?*/;
    }

    void Test2<T>(T x)
    {
        M(x)?.Self()/*T:Box<T>?*/;
        M(x)?.Value()/*T:void*/;
        if (x == null) return;
        M(x)?.Self()/*T:Box<T>?*/;
        M(x)?.Value()/*T:void*/;
    }

    void Test3(int x)
    {
        M(x)?.Self()/*T:Box<int>?*/;
        M(x)?.Value()/*T:int?*/;
        if (x == null) return; // 1
        M(x)?.Self()/*T:Box<int>?*/;
        M(x)?.Value()/*T:int?*/;
    }

    void Test4(int? x)
    {
        M(x)?.Self()/*T:Box<int?>?*/;
        M(x)?.Value()/*T:int?*/;
        if (x == null) return;
        M(x)?.Self()/*T:Box<int?>?*/;
        M(x)?.Value()/*T:int?*/;
    }

    void Test5<T>(T? x) where T : class
    {
        M(x)?.Self()/*T:Box<T?>?*/;
        M(x)?.Value()/*T:T?*/;
        if (x == null) return;
        M(x)?.Self()/*T:Box<T!>?*/;
        M(x)?.Value()/*T:T?*/;
    }

    void Test6<T>(T x) where T : struct
    {
        M(x)?.Self()/*T:Box<T>?*/;
        M(x)?.Value()/*T:T?*/;
        if (x == null) return; // 2
        M(x)?.Self()/*T:Box<T>?*/;
        M(x)?.Value()/*T:T?*/;
    }

    void Test7<T>(T? x) where T : struct
    {
        M(x)?.Self()/*T:Box<T?>?*/;
        M(x)?.Value()/*T:T?*/;
        if (x == null) return;
        M(x)?.Self()/*T:Box<T?>?*/;
        M(x)?.Value()/*T:T?*/;
    }

    void Test8<T>(T x) where T : class
    {
        M(x)?.Self()/*T:Box<T!>?*/;
        M(x)?.Value()/*T:T?*/;
        if (x == null) return;
        M(x)?.Self()/*T:Box<T!>?*/;
        M(x)?.Value()/*T:T?*/;
    }

    void Test9<T>(T x) where T : class
    {
        M(x)?.Self()/*T:Box<T!>?*/;
        M(x)?.Value()/*T:T?*/;
        if (x != null) return;
        M(x)?.Self()/*T:Box<T?>?*/;
        M(x)?.Value()/*T:T?*/;
    }

    static Box<T> M<T>(T t) => new Box<T>(t);
}

class Box<T>
{
    public Box<T> Self() => this;
    public T Value() => throw null!;
    public Box(T value) { }
}
");
            c.VerifyTypes();
            c.VerifyDiagnostics(
