        [Fact]
        [WorkItem(38010, "https://github.com/dotnet/roslyn/issues/38010")]
        public void EqualsMethod_BadArgCount()
        {
            var source = @"
#nullable enable
class C
{
    void M(System.IEquatable<string> eq1)
    {
        object.Equals();
        object.Equals(0);
        object.Equals(null, null, null);

        object.ReferenceEquals();
        object.ReferenceEquals(1);
        object.ReferenceEquals(null, null, null);

        eq1.Equals();
        eq1.Equals(true, false);

        this.Equals();
        this.Equals(null, null);
    }

    public override bool Equals(object other)
    {
        return base.Equals(other);
    }
}";
            var comp = CreateCompilation(source);
            comp.VerifyDiagnostics(
                // (3,7): warning CS0659: 'C' overrides Object.Equals(object o) but does not override Object.GetHashCode()
                // class C
                Diagnostic(ErrorCode.WRN_EqualsWithoutGetHashCode, "C").WithArguments("C").WithLocation(3, 7),
                // (7,16): error CS1501: No overload for method 'Equals' takes 0 arguments
                //         object.Equals();
                Diagnostic(ErrorCode.ERR_BadArgCount, "Equals").WithArguments("Equals", "0").WithLocation(7, 16),
                // (8,9): error CS0120: An object reference is required for the non-static field, method, or property 'object.Equals(object)'
                //         object.Equals(0);
                Diagnostic(ErrorCode.ERR_ObjectRequired, "object.Equals").WithArguments("object.Equals(object)").WithLocation(8, 9),
                // (9,16): error CS1501: No overload for method 'Equals' takes 3 arguments
                //         object.Equals(null, null, null);
                Diagnostic(ErrorCode.ERR_BadArgCount, "Equals").WithArguments("Equals", "3").WithLocation(9, 16),
                // (11,16): error CS7036: There is no argument given that corresponds to the required parameter 'objA' of 'object.ReferenceEquals(object, object)'
                //         object.ReferenceEquals();
                Diagnostic(ErrorCode.ERR_NoCorrespondingArgument, "ReferenceEquals").WithArguments("objA", "object.ReferenceEquals(object, object)").WithLocation(11, 16),
                // (12,16): error CS7036: There is no argument given that corresponds to the required parameter 'objB' of 'object.ReferenceEquals(object, object)'
                //         object.ReferenceEquals(1);
                Diagnostic(ErrorCode.ERR_NoCorrespondingArgument, "ReferenceEquals").WithArguments("objB", "object.ReferenceEquals(object, object)").WithLocation(12, 16),
                // (13,16): error CS1501: No overload for method 'ReferenceEquals' takes 3 arguments
                //         object.ReferenceEquals(null, null, null);
                Diagnostic(ErrorCode.ERR_BadArgCount, "ReferenceEquals").WithArguments("ReferenceEquals", "3").WithLocation(13, 16),
                // (15,13): error CS1501: No overload for method 'Equals' takes 0 arguments
                //         eq1.Equals();
                Diagnostic(ErrorCode.ERR_BadArgCount, "Equals").WithArguments("Equals", "0").WithLocation(15, 13),
                // (16,9): error CS0176: Member 'object.Equals(object, object)' cannot be accessed with an instance reference; qualify it with a type name instead
                //         eq1.Equals(true, false);
                Diagnostic(ErrorCode.ERR_ObjectProhibited, "eq1.Equals").WithArguments("object.Equals(object, object)").WithLocation(16, 9),
                // (18,14): error CS1501: No overload for method 'Equals' takes 0 arguments
                //         this.Equals();
                Diagnostic(ErrorCode.ERR_BadArgCount, "Equals").WithArguments("Equals", "0").WithLocation(18, 14),
                // (19,9): error CS0176: Member 'object.Equals(object, object)' cannot be accessed with an instance reference; qualify it with a type name instead
                //         this.Equals(null, null);
