        [WorkItem(36052, "https://github.com/dotnet/roslyn/issues/36052")]
        public void UnassignedLocal()
        {
            var source = @"
class Program : Base
{
    void M0()
    {
        string? x0a;
        x0a/*T:string?*/.ToString(); // 1
        string x0b;
        x0b/*T:string!*/.ToString();
    }
    void M1<T>()
    {
        T x1;
        x1/*T:T*/.ToString(); // 2
    }
    void M2(object? o)
    {
        if (o is string x2a) {}
        x2a/*T:string!*/.ToString();
        if (T() && o is var x2b) {}
        x2b/*T:object?*/.ToString(); // 3
    }
    void M3()
    {
        do
        {
        } while (T() && M<string?>(out string? s3) && s3/*T:string?*/.Length > 1); // 4
        do
        {
        } while (T() && M<string>(out string s3) && s3/*T:string!*/.Length > 1);
    }
    void M4()
    {
        while (T() || M<string?>(out string? s4))
        {
            s4/*T:string?*/.ToString(); // 5
        } 
        while (T() || M<string>(out string s4))
        {
            s4/*T:string!*/.ToString();
        }
    }
    void M5()
    {
        for (string? s1; T(); ) s1/*T:string?*/.ToString(); // 6
        for (string s1; T(); ) s1/*T:string!*/.ToString();
    }
    Program(int x) : base((T() || M<string?>(out string? s6)) && s6/*T:string?*/.Length > 1) {} // 7
    Program(long x) : base((T() || M<string>(out string s7)) && s7/*T:string!*/.Length > 1) {}
    static bool T() => true;
    static bool M<T>(out T x) { x = default(T)!; return true; }
}
class Base
{
    public Base(bool b) {}
}
";
            var comp = CreateCompilation(source, options: WithNullableEnable());
            comp.VerifyTypes();
            comp.GetDiagnostics().Where(d => d.Code != (int)ErrorCode.ERR_UseDefViolation).Verify(
                // (7,9): warning CS8602: Dereference of a possibly null reference.
                //         x0a.ToString(); // 1
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "x0a").WithLocation(7, 9),
                // (14,9): warning CS8602: Dereference of a possibly null reference.
                //         x1.ToString(); // 2
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "x1").WithLocation(14, 9),
                // (21,9): warning CS8602: Dereference of a possibly null reference.
                //         x2b.ToString(); // 3
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "x2b").WithLocation(21, 9),
                // (27,55): warning CS8602: Dereference of a possibly null reference.
                //         } while (T() && M<string?>(out string? s3) && s3.Length > 1); // 4
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "s3").WithLocation(27, 55),
                // (36,13): warning CS8602: Dereference of a possibly null reference.
                //             s4.ToString(); // 5
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "s4").WithLocation(36, 13),
                // (45,33): warning CS8602: Dereference of a possibly null reference.
                //         for (string? s1; T(); ) s1.ToString(); // 6
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "s1").WithLocation(45, 33),
                // (48,66): warning CS8602: Dereference of a possibly null reference.
                //     Program(int x) : base((T() || M<string?>(out string? s6)) && s6.Length > 1) {} // 7
                Diagnostic(ErrorCode.WRN_NullReferenceReceiver, "s6").WithLocation(48, 66));
        }

