        [Fact, WorkItem(38168, "https://github.com/dotnet/roslyn/issues/38168")]
        public void MethodTypeInference_ImplementedInterfaces_Indirect_Invariant_ObliviousVersusUnannotated()
        {
            var source = @"
#nullable enable warnings
static class P
{
    static void M(C c)
    {
        var x = c.Extension();
        x.ToString();
    }
    public static T Extension<T>(this I<T> source) => throw null!;
}

class C : I<object>, I2 {}

interface I<T> {}

#nullable enable annotations
interface I2 : I<object> {}
";
            var comp = CreateCompilation(source);
            comp.VerifyDiagnostics();
            var tree = comp.SyntaxTrees.Single();
            var declaration = tree.GetRoot().DescendantNodes().OfType<VariableDeclaratorSyntax>().Single();
            var model = comp.GetSemanticModel(tree, ignoreAccessibility: false);
            var local = (ILocalSymbol)model.GetDeclaredSymbol(declaration);
            Assert.Equal("System.Object?", local.Type.ToTestDisplayString());
            Assert.Equal(CodeAnalysis.NullableAnnotation.Annotated, local.NullableAnnotation);
            Assert.Equal(CodeAnalysis.NullableAnnotation.Annotated, local.Type.NullableAnnotation);

            var invocation = tree.GetRoot().DescendantNodes().OfType<InvocationExpressionSyntax>().First();
            Assert.Equal("c.Extension()", invocation.ToString());
            Assert.Equal("Extension<object!>", model.GetSymbolInfo(invocation).Symbol.ToDisplayString(TypeWithAnnotations.TestDisplayFormat));
        }

