        [Fact, WorkItem(38168, "https://github.com/dotnet/roslyn/issues/38168")]
        public void MultipleIEnumerableT_UnannotatedObjectVersusAnnotatedObject()
        {
            var text = @"
using System.Collections;
using System.Collections.Generic;
#nullable enable warnings

class C<T>
{
    void M(Enumerable e)
    {
        foreach (var x in e) { }
    }
}

#nullable enable
interface I : IEnumerable<C<object?>> { }

class Enumerable : IEnumerable<C<object>>, I
#nullable disable
{
    IEnumerator<C<object>> IEnumerable<C<object>>.GetEnumerator() { throw null!; }
    IEnumerator IEnumerable.GetEnumerator() { throw null!; }
}
";

            var comp = CreateCompilation(text);
            comp.VerifyDiagnostics(
                // (17,7): warning CS8645: 'IEnumerable<C<object?>>' is already listed in the interface list on type 'Enumerable' with different nullability of reference types.
                // class Enumerable : IEnumerable<C<object>>, I
                Diagnostic(ErrorCode.WRN_DuplicateInterfaceWithNullabilityMismatchInBaseList, "Enumerable").WithArguments("System.Collections.Generic.IEnumerable<C<object?>>", "Enumerable").WithLocation(17, 7)
                );
            var tree = comp.SyntaxTrees.Single();
            var @foreach = tree.GetRoot().DescendantNodes().OfType<ForEachStatementSyntax>().Single();
            var model = comp.GetSemanticModel(tree, ignoreAccessibility: false);
            Assert.Equal("C<System.Object>", model.GetForEachStatementInfo(@foreach).ElementType.ToTestDisplayString());
        }

