        [Fact, WorkItem(42837, "https://github.com/dotnet/roslyn/issues/42837")]
        public void NullableDirectivesInSpeculativeModel()
        {
            var source = @"
#nullable enable

public class C<TSymbol> where TSymbol : class, ISymbolInternal
{
    public object? _uniqueSymbolOrArities;

    private bool HasUniqueSymbol => false;

    public void GetUniqueSymbolOrArities(out IArityEnumerable? arities, out TSymbol? uniqueSymbol)
    {
        if (this.HasUniqueSymbol)
        {
            arities = null;
#nullable disable // Can '_uniqueSymbolOrArities' be null? https://github.com/dotnet/roslyn/issues/39166
            uniqueSymbol = (TSymbol)_uniqueSymbolOrArities;
#nullable enable
        }
    }
}

interface IArityEnumerable { }
interface ISymbolInternal { }
";

            var comp = CreateNullableCompilation(source);
            var tree = comp.SyntaxTrees.Single();
            var model = comp.GetSemanticModel(tree);

            var root = tree.GetRoot();
            var ifStatement = root.DescendantNodes().OfType<IfStatementSyntax>().Single();
            var cast = ifStatement.DescendantNodes().OfType<CastExpressionSyntax>().Single();
            var replaceWith = cast.Expression;

            var newIfStatement = ifStatement.ReplaceNode(cast, replaceWith);
            Assert.True(model.TryGetSpeculativeSemanticModel(
                ifStatement.SpanStart,
                newIfStatement,
                out var speculativeModel));

            var assignment = newIfStatement.DescendantNodes()
                .OfType<AssignmentExpressionSyntax>()
                .ElementAt(1);

            var info = speculativeModel.GetSymbolInfo(assignment);
            Assert.Null(info.Symbol);

            var typeInfo = speculativeModel.GetTypeInfo(assignment);
            Assert.Equal(CodeAnalysis.NullableAnnotation.Annotated, typeInfo.Nullability.Annotation);
        }

