        [Fact]
        [WorkItem(38638, "https://github.com/dotnet/roslyn/issues/38638")]
        public void MaybeNullT_Join()
        {
            var source =
@"#nullable enable
class C<T> where T : new()
{
    static T F1(bool b)
    {
        T t1;
        if (b) t1 = default(T);
        else t1 = default(T);
        return t1; // 1
    }
    static T F2(bool b, T t)
    {
        T t2;
        if (b) t2 = default(T);
        else t2 = t;
        return t2; // 2
    }
    static T F3(bool b)
    {
