        [Fact]
        [WorkItem(38638, "https://github.com/dotnet/roslyn/issues/38638")]
        public void MaybeNullT_01()
        {
            var source =
@"#nullable enable
using System;
using System.Diagnostics.CodeAnalysis;
class C<T> where T : class?
{
    public C(T x) => f = x;
    T f;
                T P1 { get => f;        set => f = value; }
    [AllowNull] T P2 { get => f;        set => f = value ?? throw new ArgumentNullException(); }
    [MaybeNull] T P3 { get => default!; set => f = value; }
    void M1()
    {
        P1 = null; // 1
        P2 = null;
        P3 = null; // 2
    }
    void M2()
    {
        f = P1;
        f = P2;
        f = P3; // 3
    }
}";
            var comp = CreateCompilation(new[] { source, AllowNullAttributeDefinition, MaybeNullAttributeDefinition });
            comp.VerifyDiagnostics(
                // (13,14): warning CS8625: Cannot convert null literal to non-nullable reference type.
                //         P1 = null; // 1
                Diagnostic(ErrorCode.WRN_NullAsNonNullable, "null").WithLocation(13, 14),
                // (15,14): warning CS8625: Cannot convert null literal to non-nullable reference type.
                //         P3 = null; // 2
                Diagnostic(ErrorCode.WRN_NullAsNonNullable, "null").WithLocation(15, 14),
                // (21,13): warning CS8601: Possible null reference assignment.
                //         f = P3; // 3
                Diagnostic(ErrorCode.WRN_NullReferenceAssignment, "P3").WithLocation(21, 13));
        }

