    static void FD<T>([DisallowNull]T x, [DisallowNull]ref T y) { y = x; }
    static void FE<T>([DisallowNull]T x,    [MaybeNull]ref T y) { y = x; }
    static void FF<T>([DisallowNull]T x,      [NotNull]ref T y) { y = x; }
}";
            var comp = CreateCompilation(new[] { source, AllowNullAttributeDefinition, DisallowNullAttributeDefinition, MaybeNullAttributeDefinition, NotNullAttributeDefinition });
            comp.VerifyDiagnostics(
                // (5,71): warning CS8601: Possible null reference assignment.
                //     static void F1<T>(   [AllowNull]T x,               ref T y) { y = x; } // 1
                Diagnostic(ErrorCode.WRN_NullReferenceAssignment, "x").WithLocation(5, 71),
                // (6,71): warning CS8601: Possible null reference assignment.
                //     static void F2<T>(   [AllowNull]T x,    [AllowNull]ref T y) { y = x; } // 2
                Diagnostic(ErrorCode.WRN_NullReferenceAssignment, "x").WithLocation(6, 71),
                // (7,71): warning CS8601: Possible null reference assignment.
                //     static void F3<T>(   [AllowNull]T x, [DisallowNull]ref T y) { y = x; } // 3
                Diagnostic(ErrorCode.WRN_NullReferenceAssignment, "x").WithLocation(7, 71),
                // (9,71): warning CS8601: Possible null reference assignment.
                //     static void F5<T>(   [AllowNull]T x,      [NotNull]ref T y) { y = x; } // 4
