        [Fact]
        [WorkItem(38638, "https://github.com/dotnet/roslyn/issues/38638")]
        public void MaybeNullT_29()
        {
            var source =
@"#nullable enable
class Program
{
    static T F1<T>()
    {
        (T t1, T t2) = (default, default);
        return t1; // 1
    }
    static T F2<T>()
    {
        T t2;
        (_, t2) = (default(T), default(T));
        return t2; // 2
    }
}";
            var comp = CreateCompilation(source, parseOptions: TestOptions.Regular8);
            comp.VerifyDiagnostics(
                // (7,16): warning CS8603: Possible null reference return.
                //         return t1; // 1
                Diagnostic(ErrorCode.WRN_NullReferenceReturn, "t1").WithLocation(7, 16),
                // (13,16): warning CS8603: Possible null reference return.
                //         return t2; // 2
                Diagnostic(ErrorCode.WRN_NullReferenceReturn, "t2").WithLocation(13, 16));
        }

        [Fact]
        public void UnconstrainedTypeParameter_01()
        {
            var source =
@"#nullable enable
class Program
{
    static void F<T, U>(U? u) where U : T
    {
        T? t = u;
    }
}";
            var comp = CreateCompilation(source, parseOptions: TestOptions.Regular8);
            comp.VerifyDiagnostics(
                // (4,25): error CS8627: A nullable type parameter must be known to be a value type or non-nullable reference type unless language version '9.0' or greater is used. Consider changing the language version or adding a 'class', 'struct', or type constraint.
                //     static void F<T, U>(U? u) where U : T
                Diagnostic(ErrorCode.ERR_NullableUnconstrainedTypeParameter, "U?").WithArguments("9.0").WithLocation(4, 25),
                // (6,9): error CS8627: A nullable type parameter must be known to be a value type or non-nullable reference type unless language version '9.0' or greater is used. Consider changing the language version or adding a 'class', 'struct', or type constraint.
                //         T? t = u;
                Diagnostic(ErrorCode.ERR_NullableUnconstrainedTypeParameter, "T?").WithArguments("9.0").WithLocation(6, 9));

            comp = CreateCompilation(source, parseOptions: TestOptions.Regular9);
            comp.VerifyDiagnostics();
        }

        [Theory]
        [CombinatorialData]
        public void UnconstrainedTypeParameter_02(bool useCompilationReference)
        {
            var sourceA =
@"#nullable enable
public abstract class A
{
    public abstract void F<T>(T? t);
}";
            var comp = CreateCompilation(sourceA, parseOptions: TestOptions.Regular8);
            comp.VerifyDiagnostics(
                // (4,31): error CS8627: A nullable type parameter must be known to be a value type or non-nullable reference type unless language version '9.0' or greater is used. Consider changing the language version or adding a 'class', 'struct', or type constraint.
                //     public abstract void F<T>(T? t);
                Diagnostic(ErrorCode.ERR_NullableUnconstrainedTypeParameter, "T?").WithArguments("9.0").WithLocation(4, 31));

            comp = CreateCompilation(sourceA, parseOptions: TestOptions.Regular9);
            comp.VerifyDiagnostics();
            var refA = AsReference(comp, useCompilationReference);

            var sourceB =
@"#nullable enable
abstract class B : A
{
    public abstract override void F<T>(T? t) where T : default;
}";
            comp = CreateCompilation(sourceB, references: new[] { refA }, parseOptions: TestOptions.Regular8);
            comp.VerifyDiagnostics(
                // (4,40): error CS8627: A nullable type parameter must be known to be a value type or non-nullable reference type unless language version '9.0' or greater is used. Consider changing the language version or adding a 'class', 'struct', or type constraint.
                //     public abstract override void F<T>(T? t) where T : default;
                Diagnostic(ErrorCode.ERR_NullableUnconstrainedTypeParameter, "T?").WithArguments("9.0").WithLocation(4, 40),
                // (4,56): error CS8400: Feature 'default type parameter constraints' is not available in C# 8.0. Please use language version 9.0 or greater.
                //     public abstract override void F<T>(T? t) where T : default;
                Diagnostic(ErrorCode.ERR_FeatureNotAvailableInVersion8, "default").WithArguments("default type parameter constraints", "9.0").WithLocation(4, 56));
            verifyMethod(comp);

            comp = CreateCompilation(sourceB, references: new[] { refA }, parseOptions: TestOptions.Regular9);
            comp.VerifyDiagnostics();
            verifyMethod(comp);

            static void verifyMethod(CSharpCompilation comp)
            {
                var method = comp.GetMember<MethodSymbol>("B.F");
                Assert.Equal("void B.F<T>(T? t)", method.ToTestDisplayString(includeNonNullable: true));
                var parameterType = method.Parameters[0].TypeWithAnnotations;
                Assert.Equal(NullableAnnotation.Annotated, parameterType.NullableAnnotation);
            }
        }

