        [Fact]
        public void UnconstrainedTypeParameter_04()
        {
            var source =
@"#nullable enable
abstract class A
{
    internal abstract void F1<T>(T? t) where T : struct;
    internal abstract void F2<T>(T? t) where T : class;
}
class B0 : A
{
    internal override void F1<T>(T? t) { }
    internal override void F2<T>(T? t) { }
}
class B1 : A
{
    internal override void F1<T>(T? t) where T : default { }
    internal override void F2<T>(T? t) where T : default { }
}
class B2 : A
{
    internal override void F1<T>(T? t) where T : struct, default { }
    internal override void F2<T>(T? t) where T : class, default { }
}
class B3 : A
{
    internal override void F1<T>(T? t) where T : default, struct { }
    internal override void F2<T>(T? t) where T : default, class { }
}";
            var comp = CreateCompilation(source, parseOptions: TestOptions.Regular9);
            comp.VerifyDiagnostics(
                // (7,7): error CS0534: 'B0' does not implement inherited abstract member 'A.F2<T>(T?)'
                // class B0 : A
                Diagnostic(ErrorCode.ERR_UnimplementedAbstractMethod, "B0").WithArguments("B0", "A.F2<T>(T?)").WithLocation(7, 7),
                // (10,28): error CS0115: 'B0.F2<T>(T?)': no suitable method found to override
