        // All pairs of methods "static void F<T>(T[?] t) [where T : _constraint_] { }".
        [Theory]
        [CombinatorialData]
        public void UnconstrainedTypeParameter_06(
            [CombinatorialValues(null, "class", "class?", "struct", "notnull", "unmanaged", "I", "I?")] string constraintA,
            bool annotatedA,
            [CombinatorialValues(null, "class", "class?", "struct", "notnull", "unmanaged", "I", "I?")] string constraintB,
            bool annotatedB)
        {
            var source =
$@"#nullable enable
class C
{{
    {getMethod(constraintA, annotatedA)}
    {getMethod(constraintB, annotatedB)}
}}
interface I
{{
}}";
            var comp = CreateCompilation(source, parseOptions: TestOptions.Regular9);
            var expectedDiagnostics = (isNullableOfT(constraintA, annotatedA) == isNullableOfT(constraintB, annotatedB)) ?
                new[]
                {
                    // (5,17): error CS0111: Type 'C' already defines a member called 'F' with the same parameter types
                    Diagnostic(ErrorCode.ERR_MemberAlreadyExists, "F").WithArguments("F", "C").WithLocation(5, 17),
                } :
                Array.Empty<DiagnosticDescription>();
            comp.VerifyDiagnostics(expectedDiagnostics);

            static string getMethod(string constraint, bool annotated) => $"static void F<T>(T{(annotated ? "?" : "")} t) {(constraint is null ? "" : $"where T : {constraint}")} {{ }}";
            static bool isNullableOfT(string constraint, bool annotated) => (constraint == "struct" || constraint == "unmanaged") && annotated;
        }

        [Theory]
        [CombinatorialData]
        public void UnconstrainedTypeParameter_07(
            [CombinatorialValues(null, "notnull", "I", "I?")] string constraint,
            bool useCompilationReference)
        {
            var sourceA =
$@"#nullable enable
public interface I
{{
}}
public abstract class A
{{
    public abstract void F<T>(T? t) {(constraint is null ? "" : $"where T : {constraint}")};
    public abstract void F<T>(T? t) where T : struct;
}}";
            var comp = CreateCompilation(sourceA, parseOptions: TestOptions.Regular9);
            comp.VerifyDiagnostics();
            var refA = AsReference(comp, useCompilationReference);

            var sourceB =
@"#nullable enable
class B1 : A
{
    public override void F<T>(T? t) { }
}
class B2 : A
{
    public override void F<T>(T? t) where T : default { }
}
class B3 : A
{
    public override void F<T>(T? t) where T : struct { }
}
class B4 : A
{
    public override void F<T>(T? t) where T : default { }
    public override void F<T>(T? t) where T : struct { }
}";
            comp = CreateCompilation(sourceB, references: new[] { refA }, parseOptions: TestOptions.Regular9);
            comp.VerifyDiagnostics(
                // (2,7): error CS0534: 'B1' does not implement inherited abstract member 'A.F<T>(T?)'
                // class B1 : A
                Diagnostic(ErrorCode.ERR_UnimplementedAbstractMethod, "B1").WithArguments("B1", "A.F<T>(T?)").WithLocation(2, 7),
                // (6,7): error CS0534: 'B2' does not implement inherited abstract member 'A.F<T>(T?)'
                // class B2 : A
                Diagnostic(ErrorCode.ERR_UnimplementedAbstractMethod, "B2").WithArguments("B2", "A.F<T>(T?)").WithLocation(6, 7),
                // (10,7): error CS0534: 'B3' does not implement inherited abstract member 'A.F<T>(T?)'
                // class B3 : A
                Diagnostic(ErrorCode.ERR_UnimplementedAbstractMethod, "B3").WithArguments("B3", "A.F<T>(T?)").WithLocation(10, 7));

            Assert.True(comp.GetMember<MethodSymbol>("B1.F").TypeParameters[0].IsValueType);
            Assert.False(comp.GetMember<MethodSymbol>("B2.F").TypeParameters[0].IsValueType);
            Assert.True(comp.GetMember<MethodSymbol>("B3.F").TypeParameters[0].IsValueType);
        }

        [Fact]
        public void UnconstrainedTypeParameter_08()
        {
            var source =
@"abstract class A<T>
{
    public abstract void F1<U>(T t);
    public abstract void F1<U>(object o) where U : class;
    public abstract void F2<U>(T t) where U : struct;
    public abstract void F2<U>(object o);
}
abstract class B1 : A<object>
{
    public override void F1<U>(object o) { }
    public override void F2<U>(object o) { }
}
abstract class B2 : A<object>
{
    public override void F1<U>(object o) where U : class { }
    public override void F2<U>(object o) where U : struct { }
}
abstract class B3 : A<object>
{
    public override void F1<U>(object o) where U : default { }
    public override void F2<U>(object o) where U : default { }
}";
            var comp = CreateCompilation(source, parseOptions: TestOptions.Regular9);
            comp.VerifyDiagnostics(
                // (3,26): warning CS1957: Member 'B1.F1<U>(object)' overrides 'A<object>.F1<U>(object)'. There are multiple override candidates at run-time. It is implementation dependent which method will be called.
