        [Theory]
        [CombinatorialData]
        public void UnconstrainedTypeParameter_34([CombinatorialValues(null, "class", "class?", "notnull")] string constraint, bool useCompilationReference)
        {
            var sourceA =
@"#nullable enable
public class A<T>
{
    public static void F<U>(U u) where U : T { }
}";
            var comp = CreateCompilation(sourceA, parseOptions: TestOptions.Regular9);
            comp.VerifyDiagnostics();
            var refA = AsReference(comp, useCompilationReference);

            var fullConstraint = constraint is null ? "" : ("where T : " + constraint);
            var sourceB =
$@"#nullable enable
class B
{{
    static void M1<T, U>(bool b, U x, U? y) {fullConstraint} where U : T
    {{
        if (b) A<T>.F<U>(x);
        if (b) A<T>.F<U>(y); // 1
        if (b) A<T>.F<U?>(x); // 2
        if (b) A<T>.F<U?>(y); // 3
        A<T>.F(x);
        A<T>.F(y); // 4
    }}
    static void M2<T, U>(bool b, U x, U? y) {fullConstraint} where U : T?
    {{
        if (b) A<T>.F<U>(x); // 5
        if (b) A<T>.F<U>(y); // 6
        if (b) A<T>.F<U?>(x); // 7
        if (b) A<T>.F<U?>(y); // 8
        if (b) A<T>.F(x); // 9
        if (b) A<T>.F(y); // 10
    }}
}}";
            comp = CreateCompilation(sourceB, references: new[] { refA }, parseOptions: TestOptions.Regular9);
            comp.VerifyDiagnostics(
                // (7,26): warning CS8604: Possible null reference argument for parameter 'u' in 'void A<T>.F<U>(U u)'.
                //         if (b) A<T>.F<U>(y); // 1
                Diagnostic(ErrorCode.WRN_NullReferenceArgument, "y").WithArguments("u", "void A<T>.F<U>(U u)").WithLocation(7, 26),
                // (8,16): warning CS8631: The type 'U?' cannot be used as type parameter 'U' in the generic type or method 'A<T>.F<U>(U)'. Nullability of type argument 'U?' doesn't match constraint type 'T'.
                //         if (b) A<T>.F<U?>(x); // 2
