    {
        default(T1).ToString(); // 1
        default(T1?).ToString(); // 2
        default(T2).ToString(); // 3
        default(T2?).ToString(); // 4
        default(T3).ToString(); // 5
        default(T3?).ToString(); // 6
        default(T4).ToString(); // 7
