        [Fact]
        public void UnconstrainedTypeParameter_37()
        {
            var source =
@"#nullable enable
class Program
{
    static T F1<T>()
    {
        T? t1 = default(T);
        return t1; // 1
    }
    static T F2<T>() where T : class
    {
        T? t2 = default(T);
        return t2; // 2
    }
    static T F3<T>() where T : class?
    {
        T? t3 = default(T);
        return t3; // 3
    }
    static T F4<T>() where T : notnull
    {
        T? t4 = default(T);
        return t4; // 4
    }
    static T F5<T, U>() where U : T?
    {
        T? t5 = default(U);
        return t5; // 5
    }
}";
            var comp = CreateCompilation(source, parseOptions: TestOptions.Regular9);
            comp.VerifyDiagnostics(
                // (7,16): warning CS8603: Possible null reference return.
                //         return t1; // 1
                Diagnostic(ErrorCode.WRN_NullReferenceReturn, "t1").WithLocation(7, 16),
                // (12,16): warning CS8603: Possible null reference return.
                //         return t2; // 2
                Diagnostic(ErrorCode.WRN_NullReferenceReturn, "t2").WithLocation(12, 16),
                // (17,16): warning CS8603: Possible null reference return.
                //         return t3; // 3
                Diagnostic(ErrorCode.WRN_NullReferenceReturn, "t3").WithLocation(17, 16),
                // (22,16): warning CS8603: Possible null reference return.
                //         return t4; // 4
                Diagnostic(ErrorCode.WRN_NullReferenceReturn, "t4").WithLocation(22, 16),
                // (27,16): warning CS8603: Possible null reference return.
                //         return t5; // 5
                Diagnostic(ErrorCode.WRN_NullReferenceReturn, "t5").WithLocation(27, 16));

            var tree = comp.SyntaxTrees[0];
            var model = comp.GetSemanticModel(tree);
            var locals = tree.GetRoot().DescendantNodes().OfType<VariableDeclaratorSyntax>().ToArray();
            Assert.Equal(5, locals.Length);
            VerifyVariableAnnotation(model, locals[0], "T? t1", NullableAnnotation.Annotated);
            VerifyVariableAnnotation(model, locals[1], "T? t2", NullableAnnotation.Annotated);
            VerifyVariableAnnotation(model, locals[2], "T? t3", NullableAnnotation.Annotated);
            VerifyVariableAnnotation(model, locals[3], "T? t4", NullableAnnotation.Annotated);
            VerifyVariableAnnotation(model, locals[4], "T? t5", NullableAnnotation.Annotated);
        }

        [Fact]
        [WorkItem(46236, "https://github.com/dotnet/roslyn/issues/46236")]
        public void UnconstrainedTypeParameter_38()
        {
            var source =
@"#nullable enable
class Program
{
    static T F1<T>(T x1)
    {
        var y1 = x1;
        y1 = default(T);
        return y1; // 1
    }
    static T F2<T>(T x2) where T : class
    {
        var y2 = x2;
        y2 = default(T);
        return y2; // 2
    }
    static T F3<T>(T x3) where T : class?
    {
        var y3 = x3;
        y3 = default(T);
        return y3; // 3
    }
    static T F4<T>(T x4) where T : notnull
    {
        var y4 = x4;
        y4 = default(T);
        return y4; // 4
    }
    static T F5<T, U>(U x5) where U : T?
    {
        var y5 = x5;
        y5 = default(U);
        return y5; // 5
    }
}";
            var comp = CreateCompilation(source, parseOptions: TestOptions.Regular9);
            comp.VerifyDiagnostics(
                // (8,16): warning CS8603: Possible null reference return.
                //         return y1; // 1
                Diagnostic(ErrorCode.WRN_NullReferenceReturn, "y1").WithLocation(8, 16),
                // (14,16): warning CS8603: Possible null reference return.
                //         return y2; // 2
                Diagnostic(ErrorCode.WRN_NullReferenceReturn, "y2").WithLocation(14, 16),
                // (20,16): warning CS8603: Possible null reference return.
                //         return y3; // 3
                Diagnostic(ErrorCode.WRN_NullReferenceReturn, "y3").WithLocation(20, 16),
                // (26,16): warning CS8603: Possible null reference return.
                //         return y4; // 4
                Diagnostic(ErrorCode.WRN_NullReferenceReturn, "y4").WithLocation(26, 16),
                // (32,16): warning CS8603: Possible null reference return.
                //         return y5; // 5
                Diagnostic(ErrorCode.WRN_NullReferenceReturn, "y5").WithLocation(32, 16));

            var tree = comp.SyntaxTrees[0];
            var model = comp.GetSemanticModel(tree);
            var locals = tree.GetRoot().DescendantNodes().OfType<VariableDeclaratorSyntax>().ToArray();
            Assert.Equal(5, locals.Length);
            // https://github.com/dotnet/roslyn/issues/46236: Locals should be treated as annotated.
            VerifyVariableAnnotation(model, locals[0], "T? y1", NullableAnnotation.Annotated);
            VerifyVariableAnnotation(model, locals[1], "T? y2", NullableAnnotation.Annotated);
            VerifyVariableAnnotation(model, locals[2], "T? y3", NullableAnnotation.Annotated);
            VerifyVariableAnnotation(model, locals[3], "T? y4", NullableAnnotation.Annotated);
            VerifyVariableAnnotation(model, locals[4], "U? y5", NullableAnnotation.Annotated);
        }

        private static void VerifyVariableAnnotation(SemanticModel model, VariableDeclaratorSyntax syntax, string expectedDisplay, NullableAnnotation expectedAnnotation)
        {
            var symbol = (ILocalSymbol)model.GetDeclaredSymbol(syntax);
            Assert.Equal(expectedDisplay, symbol.ToTestDisplayString(includeNonNullable: true));
            Assert.Equal(
                (expectedAnnotation == NullableAnnotation.Annotated) ? CodeAnalysis.NullableAnnotation.Annotated : CodeAnalysis.NullableAnnotation.NotAnnotated,
                symbol.Type.NullableAnnotation);
            Assert.Equal(expectedAnnotation, symbol.GetSymbol<LocalSymbol>().TypeWithAnnotations.NullableAnnotation);
        }

