        [Fact]
        public void UnconstrainedTypeParameter_43()
        {
            var source =
@"#nullable enable
class Program
{
    static T F1<T>(bool b, T x1, T? y1)
    {
        if (b) return new[] { y1, x1 }[0]; // 1
        return new[] { x1, y1 }[0]; // 2
    }
    static T F2<T>(bool b, T x2, T? y2) where T : class?
    {
        if (b) return new[] { y2, x2 }[0]; // 3
        return new[] { x2, y2 }[0]; // 4
    }
    static T F3<T>(bool b, T x3, T? y3) where T : notnull
    {
        if (b) return new[] { y3, x3 }[0]; // 5
        return new[] { x3, y3 }[0]; // 6
    }
}";
            var comp = CreateCompilation(source, parseOptions: TestOptions.Regular9);
            comp.VerifyDiagnostics(
                // (6,23): warning CS8603: Possible null reference return.
                //         if (b) return new[] { y1, x1 }[0]; // 1
                Diagnostic(ErrorCode.WRN_NullReferenceReturn, "new[] { y1, x1 }[0]").WithLocation(6, 23),
                // (7,16): warning CS8603: Possible null reference return.
                //         return new[] { x1, y1 }[0]; // 2
                Diagnostic(ErrorCode.WRN_NullReferenceReturn, "new[] { x1, y1 }[0]").WithLocation(7, 16),
                // (11,23): warning CS8603: Possible null reference return.
                //         if (b) return new[] { y2, x2 }[0]; // 3
                Diagnostic(ErrorCode.WRN_NullReferenceReturn, "new[] { y2, x2 }[0]").WithLocation(11, 23),
                // (12,16): warning CS8603: Possible null reference return.
                //         return new[] { x2, y2 }[0]; // 4
                Diagnostic(ErrorCode.WRN_NullReferenceReturn, "new[] { x2, y2 }[0]").WithLocation(12, 16),
                // (16,23): warning CS8603: Possible null reference return.
                //         if (b) return new[] { y3, x3 }[0]; // 5
                Diagnostic(ErrorCode.WRN_NullReferenceReturn, "new[] { y3, x3 }[0]").WithLocation(16, 23),
                // (17,16): warning CS8603: Possible null reference return.
                //         return new[] { x3, y3 }[0]; // 6
                Diagnostic(ErrorCode.WRN_NullReferenceReturn, "new[] { x3, y3 }[0]").WithLocation(17, 16));
        }

