        [WorkItem(40430, "https://github.com/dotnet/roslyn/issues/40430")]
        public void DecodingWithMissingNullableAttribute(bool useImageReference)
        {
            var nullableAttrComp = CreateCompilation(NullableAttributeDefinition);
            nullableAttrComp.VerifyDiagnostics();
            var nullableAttrRef = useImageReference ? nullableAttrComp.EmitToImageReference() : nullableAttrComp.ToMetadataReference();

            var lib_cs = @"
#nullable enable
public class C3<T1, T2, T3>
{
}

public class SelfReferencing
    : C3<SelfReferencing, string?, string>
{
    public SelfReferencing()
    {
        System.Console.Write(""ran"");
    }
}
";
            var lib = CreateCompilation(lib_cs, references: new[] { nullableAttrRef });
            lib.VerifyDiagnostics();
            var libRef = useImageReference ? lib.EmitToImageReference() : lib.ToMetadataReference();

            var source_cs = @"
public class C2
{
    public static void M()
    {
        _ = new SelfReferencing();
    }
}
";
            var comp = CreateCompilation(source_cs, references: new[] { libRef });
            comp.VerifyEmitDiagnostics();

            var executable_cs = @"
public class C
{
    public static void Main()
    {
        C2.M();
    }
}";

            var executeComp = CreateCompilation(executable_cs,
                references: new[] { comp.EmitToImageReference(), libRef, nullableAttrRef },
                options: TestOptions.DebugExe);
            CompileAndVerify(executeComp, expectedOutput: "ran");
        }

