        [Fact]
        [WorkItem(48992, "https://github.com/dotnet/roslyn/issues/48992")]
        public void TryGetValue_GenericMethod()
        {
            var source =
@"#nullable enable
using System.Diagnostics.CodeAnalysis;
class Collection
{
    public bool TryGetValue<T>(object key, [MaybeNullWhen(false)] out T value)
    {
        value = default;
        return false;
    }
}
class Program
{
    static string GetValue1(Collection c, object key)
    {
        // out string
        if (c.TryGetValue(key, out string s1)) // 1
        {
            return s1;
        }
        // out string?
        if (c.TryGetValue(key, out string? s2))
        {
            return s2; // 2
        }
        // out string?, explicit type argument
        if (c.TryGetValue<string>(key, out string? s3))
        {
            return s3;
        }
        // out var, explicit type argument
        if (c.TryGetValue<string>(key, out var s4))
        {
            return s4;
        }
        return string.Empty;
    }
    static T GetValue2<T>(Collection c, object key)
    {
        // out T
        if (c.TryGetValue(key, out T s1)) // 3
        {
            return s1;
        }
        // out T?
        if (c.TryGetValue(key, out T? s2))
        {
            return s2; // 4
        }
        // out T?, explicit type argument
        if (c.TryGetValue<T>(key, out T? s3))
        {
            return s3;
        }
        // out var, explicit type argument
        if (c.TryGetValue<T>(key, out var s4))
        {
            return s4;
        }
        return default!;
    }
}";
            var comp = CreateCompilation(new[] { source, MaybeNullWhenAttributeDefinition });
            comp.VerifyEmitDiagnostics(
                // (16,36): warning CS8600: Converting null literal or possible null value to non-nullable type.
                //         if (c.TryGetValue(key, out string s1)) // 1
                Diagnostic(ErrorCode.WRN_ConvertingNullableToNonNullable, "string s1").WithLocation(16, 36),
                // (23,20): warning CS8603: Possible null reference return.
                //             return s2; // 2
                Diagnostic(ErrorCode.WRN_NullReferenceReturn, "s2").WithLocation(23, 20),
                // (40,36): warning CS8600: Converting null literal or possible null value to non-nullable type.
                //         if (c.TryGetValue(key, out T s1)) // 3
                Diagnostic(ErrorCode.WRN_ConvertingNullableToNonNullable, "T s1").WithLocation(40, 36),
                // (47,20): warning CS8603: Possible null reference return.
                //             return s2; // 4
                Diagnostic(ErrorCode.WRN_NullReferenceReturn, "s2").WithLocation(47, 20));
        }

