        [Fact]
        [WorkItem(50097, "https://github.com/dotnet/roslyn/issues/50097")]
        public void Issue50097()
        {
            var src = @"
using System;

public class C
{
    static void Main()
    {
    }
    
    public record AuditedItem<T>(T Value, string ConcurrencyToken, DateTimeOffset LastChange)
        where T : class;

    public record FieldItem(object? Value, string ConcurrencyToken, DateTimeOffset LastChange)
        : AuditedItem<object?>(Value, ConcurrencyToken, LastChange);
}

namespace System.Runtime.CompilerServices
{
    public static class IsExternalInit
    {
    }
}
";
            var comp = CreateCompilation(src, options: TestOptions.DebugExe.WithNullableContextOptions(NullableContextOptions.Enable));
            var diagnostics = comp.GetEmitDiagnostics();

            diagnostics.Verify(
                // (13,19): warning CS8634: The type 'object?' cannot be used as type parameter 'T' in the generic type or method 'C.AuditedItem<T>'. Nullability of type argument 'object?' doesn't match 'class' constraint.
                //     public record FieldItem(object? Value, string ConcurrencyToken, DateTimeOffset LastChange)
                Diagnostic(ErrorCode.WRN_NullabilityMismatchInTypeParameterReferenceTypeConstraint, "FieldItem").WithArguments("C.AuditedItem<T>", "T", "object?").WithLocation(13, 19),
                // (13,19): warning CS8634: The type 'object?' cannot be used as type parameter 'T' in the generic type or method 'C.AuditedItem<T>'. Nullability of type argument 'object?' doesn't match 'class' constraint.
                //     public record FieldItem(object? Value, string ConcurrencyToken, DateTimeOffset LastChange)
                Diagnostic(ErrorCode.WRN_NullabilityMismatchInTypeParameterReferenceTypeConstraint, "FieldItem").WithArguments("C.AuditedItem<T>", "T", "object?").WithLocation(13, 19),
                // (13,19): warning CS8634: The type 'object?' cannot be used as type parameter 'T' in the generic type or method 'C.AuditedItem<T>'. Nullability of type argument 'object?' doesn't match 'class' constraint.
                //     public record FieldItem(object? Value, string ConcurrencyToken, DateTimeOffset LastChange)
                Diagnostic(ErrorCode.WRN_NullabilityMismatchInTypeParameterReferenceTypeConstraint, "FieldItem").WithArguments("C.AuditedItem<T>", "T", "object?").WithLocation(13, 19)
                );

            var reportedDiagnostics = new HashSet<Diagnostic>();
            reportedDiagnostics.AddAll(diagnostics);
            Assert.Equal(1, reportedDiagnostics.Count);
        }

        [Fact]
        public void AmbigMember_DynamicDifferences()
        {
            var src = @"
interface I<T> { T Item { get; } }

interface I2<T> : I<T> { }

interface I3 : I<dynamic>, I2<object> { }

public class C
{
    void M(I3 i)
    {
        _ = i.Item;
    }
}
";
            var comp = CreateCompilation(src);
            comp.VerifyDiagnostics(
                // (6,11): error CS8779: 'I<object>' is already listed in the interface list on type 'I3' as 'I<dynamic>'.
                // interface I3 : I<dynamic>, I2<object> { }
                Diagnostic(ErrorCode.ERR_DuplicateInterfaceWithDifferencesInBaseList, "I3").WithArguments("I<object>", "I<dynamic>", "I3").WithLocation(6, 11),
                // (6,16): error CS1966: 'I3': cannot implement a dynamic interface 'I<dynamic>'
                // interface I3 : I<dynamic>, I2<object> { }
                Diagnostic(ErrorCode.ERR_DeriveFromConstructedDynamic, "I<dynamic>").WithArguments("I3", "I<dynamic>").WithLocation(6, 16),
                // (12,15): error CS0229: Ambiguity between 'I<dynamic>.Item' and 'I<object>.Item'
                //         _ = i.Item;
                Diagnostic(ErrorCode.ERR_AmbigMember, "Item").WithArguments("I<dynamic>.Item", "I<object>.Item").WithLocation(12, 15)
                );
            var i3 = comp.GetTypeByMetadataName("I3");
            AssertEx.Equal(new string[] { "I<dynamic>", "I2<object>" },
                i3.Interfaces().ToTestDisplayStrings(TypeWithAnnotations.TestDisplayFormat));
            AssertEx.Equal(new string[] { "I<dynamic>", "I2<object>", "I<object>" },
                i3.AllInterfaces().ToTestDisplayStrings(TypeWithAnnotations.TestDisplayFormat));
        }

