        [Fact]
        public void AmbigMember_DifferenceBetweenNonnullableAndOblivious_WithoutConstraint()
        {
            var src = @"
#nullable disable
interface I<T> { T Item { get; set; } }

#nullable enable
interface I2<T> : I<T> { }

#nullable disable
interface I3 : I<object>, I2<object> { }

#nullable enable
public class C
{
    void M(I3 i)
    {
        _ = i.Item;
        i.Item = null;
    }
}
";
            var comp = CreateCompilation(src);
            comp.VerifyDiagnostics();
            var i3 = comp.GetTypeByMetadataName("I3");
            AssertEx.Equal(new string[] { "I<object>", "I2<object>" },
                i3.Interfaces().ToTestDisplayStrings(TypeWithAnnotations.TestDisplayFormat));
            AssertEx.Equal(new string[] { "I2<object>", "I<object>" },
                i3.AllInterfaces().ToTestDisplayStrings(TypeWithAnnotations.TestDisplayFormat));

            var tree = comp.SyntaxTrees.Single();
            var model = comp.GetSemanticModel(tree, ignoreAccessibility: false);
            var item = tree.GetRoot().DescendantNodes().OfType<MemberAccessExpressionSyntax>().First();
            Assert.Equal("i.Item", item.ToString());
            Assert.Equal("object", ((IPropertySymbol)model.GetSymbolInfo(item).Symbol).Type.ToDisplayString(TypeWithAnnotations.TestDisplayFormat));

            var found = model.LookupSymbols(item.SpanStart, i3.GetPublicSymbol()).Single(s => s.Name == "Item");
            Assert.Equal("object", ((IPropertySymbol)found).Type.ToDisplayString(TypeWithAnnotations.TestDisplayFormat));
        }

