        public void AmbigMember_DifferenceBetweenNonnullableAndOblivious_WithConstraint_ReverseOrder_OnTypeParameterImplementingBothInterfaces()
        {
            var src = @"
#nullable disable
interface I<T> where T : class { T Item { get; set; } }

#nullable enable
interface I2<T> : I<T> where T : class { }

public class C
{
#nullable disable
    void M<T>(T i) where T : I2<object>, I<object>
    {
#nullable enable
        _ = i.Item;
        i.Item = null;
    }
}
";
            var comp = CreateCompilation(src);
            comp.VerifyDiagnostics(
                // (15,18): warning CS8625: Cannot convert null literal to non-nullable reference type.
                //         i.Item = null;
                Diagnostic(ErrorCode.WRN_NullAsNonNullable, "null").WithLocation(15, 18)
                );

            var tree = comp.SyntaxTrees.Single();
            var model = comp.GetSemanticModel(tree, ignoreAccessibility: false);
            var item = tree.GetRoot().DescendantNodes().OfType<MemberAccessExpressionSyntax>().First();

            var t = ((MethodSymbol)comp.GetMember("C.M")).TypeParameters.Single();
            var found = model.LookupSymbols(item.SpanStart, t.GetPublicSymbol()).Single(s => s.Name == "Item");
            Assert.Equal("object!", ((IPropertySymbol)found).Type.ToDisplayString(TypeWithAnnotations.TestDisplayFormat));
        }

